/* Finot Académie — cours approfondis, vague 1 pédagogie finale (23/10/2026) : anglais 6e (cycle 3, cible CECRL A1+ en LVA / A1 en LVB bilangue).
   Même format que course-depth-maths-cm1.js (deep / try / adult / culture), affiché par js/course-depth.js.
   Rien n'est retiré des cours existants. Explications en français, exemples en anglais, pièges propres aux francophones.
   Programme de référence : anglais collège, BO n°22 du 29 mai 2025 (arrêté du 5 mai 2025), applicable en 6e depuis la rentrée 2025-2026. Faits culturels vérifiables uniquement. */
(function(root){
'use strict';
const D=root.MQCourseDepth=root.MQCourseDepth||{version:'1',chapters:{},add(map,meta){for(const id of Object.keys(map))this.chapters[id]=Object.assign({},meta,map[id]);}};
const tb=r=>'<table class="ptable">'+r.map(x=>'<tr>'+x.map(c=>'<td>'+c+'</td>').join('')+'</tr>').join('')+'</table>';
const ul=a=>'<ul>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ul>';
const ol=a=>'<ol>'+a.map(x=>'<li>'+x+'</li>').join('')+'</ol>';
D.add({
'en6a':{
 deep:[{t:'Bien choisir sa formule de salutation',h:`<p>En français, « bonjour » sert toute la journée. En anglais, on choisit selon le moment et selon la personne à qui on parle.</p>
${tb([[`<b lang="en">Hello</b> / <b lang="en">Hi</b>`,`à tout moment ; <b lang="en">Hi</b> est plus familier (entre amis)`],[`<b lang="en">Good morning</b>`,`le matin, jusqu’à midi`],[`<b lang="en">Good afternoon</b>`,`l’après-midi`],[`<b lang="en">Good evening</b>`,`en arrivant le soir`],[`<b lang="en">Good night</b>`,`seulement pour dire au revoir avant de dormir`]])}
<p>Piège classique : <b lang="en">Good night</b> ne sert <b>jamais</b> à saluer quelqu’un à 20 heures. C’est une formule d’au revoir.</p>
<p><b lang="en">How are you?</b> est une salutation, pas une vraie question de santé. On répond vite : <b lang="en">I’m fine, thank you. And you?</b> (ou <b lang="en">great</b>, <b lang="en">OK</b>, <b lang="en">not bad</b>).</p>
<p>Prononciation : dans <b lang="en">hello</b>, l’accent tonique est sur la <b lang="en">2e</b> syllabe (heh-LO). Le <b lang="en">h</b> se prononce vraiment, en soufflant un peu d’air, contrairement au français. Pour <b lang="en">thank you</b>, la langue touche le bout des dents : /θ/, pas « s ».</p>`},
 {t:'Se présenter en quatre phrases',h:`<p>Voici le « squelette » d’une présentation. Les phrases se construisent presque comme en français, sauf pour l’âge.</p>
${ol([`<b lang="en">My name is Inès.</b> ou <b lang="en">I’m Inès.</b> (Je m’appelle Inès.)`,`<b lang="en">I’m twelve.</b> (J’ai douze ans.) — avec le verbe <b>être</b>, jamais « I have twelve ».`,`<b lang="en">I’m from France.</b> ou <b lang="en">I live in Lyon.</b>`,`<b lang="en">Nice to meet you!</b> (Enchanté !)`])}
<p>Pour épeler un prénom : <b lang="en">How do you spell your name?</b> Les voyelles de l’alphabet anglais sonnent autrement qu’en français : A se dit « éï », E « i », I « aï », G « dji », J « djéï », H « éïtch ». Entraîne-toi sur ton propre prénom.</p>
<p>Exemple guidé. Mini-dialogue : <b lang="en">— Hi, I’m Tom. What’s your name? — My name’s Inès. Nice to meet you. — Nice to meet you too.</b> On répète « Nice to meet you » avec <b lang="en">too</b> (« moi aussi »). Ne dis pas « me too » pour répondre à cette phrase : <b lang="en">you too</b> est la réponse naturelle.</p>`}],
 try:{q:`Traduis en anglais : « Bonjour, je m’appelle Inès et j’ai douze ans. »`,a:`Hello, my name is Inès and I’m twelve. (On peut ajouter « years old ». Le verbe est « être » : I’m, pas « I have ».)`},
 adult:`Jouez la scène d’une rencontre : vous êtes un nouvel élève anglais et votre enfant vous accueille. Vérifiez trois choses seulement : le h de hello soufflé, « I’m twelve » (et non « I have twelve »), et « you too » en réponse à « Nice to meet you ». Faites-lui épeler son prénom en anglais.`,
 culture:{t:`Le mot hello est récent`,h:`<p>Le mot <b lang="en">hello</b> s’est répandu à la fin du XIXe siècle, avec le téléphone. On raconte qu’Alexander Graham Bell, l’un des inventeurs du téléphone, proposait de décrocher en disant <b lang="en">Ahoy!</b>, alors que Thomas Edison préférait <b lang="en">Hello</b>. C’est Hello qui l’a emporté, et il est aujourd’hui connu dans le monde entier.</p>`}},
'en6b':{
 deep:[{t:'-teen ou -ty : le piège de l’accent',h:`<p>De 13 à 19, les nombres finissent par <b lang="en">-teen</b>. Pour les dizaines, ils finissent par <b lang="en">-ty</b>. À l’oral, on les confond facilement ! Le secret est l’accent tonique :</p>
${tb([[`<b lang="en">thirTEEN</b> (13)`,`accent à la fin, voyelle longue`],[`<b lang="en">THIRty</b> (30)`,`accent au début, fin très courte`],[`<b lang="en">fourTEEN</b> / <b lang="en">FORty</b>`,`40 s’écrit sans « u »`],[`<b lang="en">fifTEEN</b> / <b lang="en">FIFty</b>`,`15 et 50 : « f », pas « v »`],[`<b lang="en">eighTEEN</b> / <b lang="en">EIGHty</b>`,`18 : eigh-teen, 80 : un seul « t »`]])}
<p>De 21 à 99, on met un trait d’union : <b lang="en">twenty-one</b>, <b lang="en">sixty-four</b>. Pour 100, on dit <b lang="en">a hundred</b> ou <b lang="en">one hundred</b> ; <b lang="en">two hundred</b> ne prend <b>pas de s</b>. En anglais britannique : <b lang="en">one hundred and five</b> (105).</p>
<p>Le <b lang="en">th</b> de <b lang="en">three</b>, <b lang="en">thirteen</b>, <b lang="en">thirty</b> est un son à part : la langue sort légèrement entre les dents.</p>`},
 {t:'Dire son âge et lire des numéros',h:`<p>Pour l’âge, on utilise <b lang="en">to be</b> : <b lang="en">How old are you? — I’m eleven.</b> (On peut dire <b lang="en">I’m eleven years old</b>, mais jamais « I’m eleven years ».) Pour une autre personne : <b lang="en">She’s thirteen.</b></p>
<p>Un numéro de téléphone se lit <b>chiffre par chiffre</b> : 07 52 → <b lang="en">oh seven, five two</b>. Le zéro se dit <b lang="en">zero</b> ou <b lang="en">oh</b> (comme la lettre O). Quand deux chiffres se répètent, on peut dire <b lang="en">double</b> : 77 → <b lang="en">double seven</b>.</p>
<p>Exemple guidé : « Mon frère a quatorze ans et ma sœur a quarante ans de moins que ma grand-mère » est trop long. Fais plus simple. <b lang="en">My brother is fourteen. My grandmother is seventy-five.</b> On écrit le trait d’union, on ne met pas de s à « years » après un adjectif composé, mais <b lang="en">a ten-year-old boy</b> (un garçon de dix ans) prend un trait d’union et pas de s.</p>
<p>Astuce : récite à voix haute 13-30, 14-40, 15-50, 16-60, 17-70, 18-80, 19-90, en insistant sur l’accent.</p>`}],
 try:{q:`Comment dit-on « J’ai treize ans, mon père a quarante-sept ans » ?`,a:`I’m thirteen. My father is forty-seven. (forty : sans « u » ; trait d’union dans forty-seven ; verbe be, pas have.)`},
 adult:`Faites un jeu d’écoute : dites « thirteen » ou « thirty » à voix haute et demandez à votre enfant d’écrire le nombre entendu (13 ou 30). Si vous hésitez sur la prononciation, retenez : -teen est long et accentué, -ty est court. Faites aussi lire à haute voix une plaque d’immatriculation ou un numéro de téléphone chiffre par chiffre.`,
 culture:{t:`Pourquoi « eleven » et « twelve » ?`,h:`<p>Les nombres 11 et 12 ne suivent pas la règle des « -teen ». Leurs ancêtres en vieil anglais signifiaient à peu près « un restant » et « deux restants » après dix. C’est pourquoi on ne dit pas « oneteen » ni « twoteen ». La régularité commence à <b lang="en">thirteen</b>.</p>`}},
'en6c':{
 deep:[{t:'L’adjectif de couleur se place avant le nom',h:`<p>En français : « un sac <b>rouge</b> ». En anglais, l’adjectif passe <b>devant</b> le nom : <b lang="en">a red bag</b>. Et surtout, il est <b>invariable</b> : on ne lui met ni s ni e.</p>
${tb([[`<b lang="en">a red bag</b>`,`un sac rouge`],[`<b lang="en">two red bags</b>`,`deux sacs rouges (red ne change pas)`],[`<b lang="en">a green pencil case</b>`,`une trousse verte`],[`<b lang="en">a light blue pen</b>`,`un stylo bleu clair`],[`<b lang="en">a dark green coat</b>`,`un manteau vert foncé`]])}
<p>Les couleurs de base : <b lang="en">red, blue, green, yellow, orange, pink, purple, brown, black, white, grey</b> (<b lang="en">gray</b> en anglais américain). Pour demander : <b lang="en">What colour is it?</b> (<b lang="en">color</b> en américain). Réponse : <b lang="en">It’s blue.</b> ; au pluriel : <b lang="en">What colour are they? — They’re blue.</b></p>
<p>Pièges de prononciation : <b lang="en">white</b> commence par un « w » (comme dans « ouate »), <b lang="en">brown</b> se prononce « braoune », et <b lang="en">purple</b> se dit « peurpeul », avec un « r » léger.</p>`},
 {t:'Objets de la classe et du sac',h:`<p>Voici du vocabulaire à connaître en contexte : <b lang="en">a book, a pen, a pencil, a ruler, a bag, a table, a chair, a computer, a window, a door</b>. Chaque nom au singulier s’emploie avec <b lang="en">a</b> (ou <b lang="en">an</b> devant une voyelle : <b lang="en">an eraser</b>).</p>
<p>Questions utiles en classe :</p>
${ul([`<b lang="en">What’s this?</b> — <b lang="en">It’s a pen.</b>`,`<b lang="en">What colour is your bag?</b> — <b lang="en">It’s black and red.</b> (deux couleurs : on relie par <b lang="en">and</b>)`,`<b lang="en">Is it a blue pen?</b> — <b lang="en">Yes, it is.</b> / <b lang="en">No, it isn’t. It’s a green pen.</b>`])}
<p>Exemple guidé. Pour décrire une scène : <b lang="en">There is a yellow bag on the chair. It’s Tom’s bag.</b> On repère l’article (<b lang="en">a</b>), la couleur avant le nom (<b lang="en">yellow bag</b>) et le verbe <b lang="en">is</b>. Évite l’erreur « a bag yellow » : c’est le mot-à-mot du français.</p>`}],
 try:{q:`Écris en anglais : « Deux stylos verts et un sac rose ».`,a:`Two green pens and a pink bag. (green ne prend pas de s ; l’adjectif est avant le nom ; pens prend le s du pluriel.)`},
 adult:`Dans la pièce, désignez cinq objets et demandez « What colour is it? » à votre enfant. Exigez l’ordre adjectif puis nom (a red cup) et l’absence de s sur la couleur (two red cups). Reformulez en anglais ses erreurs sans les souligner : « a cup red » → « Ah, a red cup! »`,
 culture:{t:`Un fruit qui a donné son nom à une couleur`,h:`<p>En anglais, le mot <b lang="en">orange</b> désignait d’abord le fruit. La couleur a pris le nom du fruit vers le XVIe siècle ; avant, on parlait de « jaune-rouge ». En français, c’est la même histoire : le fruit est antérieur au nom de la couleur. Autre curiosité : l’arc-en-ciel anglais compte sept couleurs, avec <b lang="en">indigo</b> entre bleu et violet, une habitude héritée du physicien Isaac Newton.</p>`}},
'en6d':{
 deep:[{t:'Les mots de la famille, au quotidien',h:`<p>Les mots à connaître : <b lang="en">mother / father</b> (au quotidien <b lang="en">mum / dad</b> en Grande-Bretagne, <b lang="en">mom / dad</b> aux États-Unis), <b lang="en">brother, sister, grandmother, grandfather, uncle, aunt, cousin</b>. Le mot <b lang="en">cousin</b> convient aux garçons et aux filles. <b lang="en">Parents</b> désigne seulement le père et la mère.</p>
<p>Faux ami : <b lang="en">relatives</b> signifie « membres de la famille » (oncles, cousins…), alors que <b lang="en">parents</b> veut dire « le père et la mère ». « Mes parents » se traduit <b lang="en">my parents</b>, mais « mes parents proches » se dit <b lang="en">my relatives</b>.</p>
<p>Prononciation : <b lang="en">brother</b> (« brazeur ») et <b lang="en">mother</b> (« mazeur ») contiennent le son /ð/ et un « o » qui se dit « eu/a ». <b lang="en">Daughter</b> se prononce « dotteur » : le <b lang="en">gh</b> est muet. <b lang="en">Aunt</b> se dit « aant ».</p>`},
 {t:'Présenter sa famille, compter les membres',h:`<p>Pour parler de la famille de quelqu’un, on utilise <b lang="en">’s</b> : <b lang="en">my brother’s name is Tom</b>. Ici, <b lang="en">’s</b> marque l’appartenance, pas le verbe <b lang="en">is</b>. Pour demander : <b lang="en">Have you got any brothers or sisters?</b> — <b lang="en">Yes, I’ve got one sister.</b> / <b lang="en">No, I haven’t.</b></p>
<p>Pour demander combien : <b lang="en">How many brothers have you got?</b> Le nom reste au pluriel : <b lang="en">two brothers</b>.</p>
<p>Exemple guidé de petite description : <b lang="en">This is my family. My father is Paul and my mother is Anna. I’ve got a brother. His name is Léo. He’s ten. My grandmother lives in Brest.</b></p>
${ul([`<b lang="en">his</b> parle du frère (un garçon) ; <b lang="en">her</b> parlerait d’une sœur.`,`On répète <b lang="en">my</b> devant chaque nom : <b lang="en">my mother and my father</b> reste correct.`,`Après <b lang="en">lives</b>, le s est la marque de <b lang="en">she/he</b>.`])}`}],
 try:{q:`Comment dit-on « Voici mon oncle ; sa fille est ma cousine » ?`,a:`This is my uncle. His daughter is my cousin. (his, car on parle d’un oncle : un homme.)`},
 adult:`Faites dessiner à l’enfant un arbre généalogique simple et demandez-lui de le présenter en anglais avec « This is… His/Her name is… ». Surveillez his/her (le possesseur décide) et le piège parents/relatives. Les réponses courtes à « Have you got…? » (Yes, I have / No, I haven’t) méritent plusieurs répétitions.`,
 culture:{t:`Mum ou mom ?`,h:`<p>Au Royaume-Uni, on dit <b lang="en">mum</b> ; aux États-Unis, <b lang="en">mom</b>. Même chose pour la fête : la fête des mères britannique (<b lang="en">Mothering Sunday</b>) tombe en mars, alors qu’aux États-Unis, <b lang="en">Mother’s Day</b> a lieu en mai. Quand on apprend l’anglais, on croise donc des mots et des dates qui changent selon le pays.</p>`}},
'en6e':{
 deep:[{t:'Les formes de BE et les contractions',h:`<p><b lang="en">To be</b> (être) est le verbe le plus utilisé et le plus irrégulier de la langue. Au présent :</p>
${tb([[`<b lang="en">I am</b> → <b lang="en">I’m</b>`,`<b lang="en">we are</b> → <b lang="en">we’re</b>`],[`<b lang="en">you are</b> → <b lang="en">you’re</b>`,`<b lang="en">you are</b> → <b lang="en">you’re</b>`],[`<b lang="en">he/she/it is</b> → <b lang="en">he’s, she’s, it’s</b>`,`<b lang="en">they are</b> → <b lang="en">they’re</b>`]])}
<p>La négation s’obtient en ajoutant <b lang="en">not</b> : <b lang="en">I’m not</b>, <b lang="en">he isn’t</b>, <b lang="en">they aren’t</b>. Pour poser une question, on <b>inverse</b> : <b lang="en">Are you tired?</b>, <b lang="en">Is she a teacher?</b></p>
<p>Réponses courtes : <b lang="en">Yes, I am.</b> / <b lang="en">No, I’m not.</b> Avec « yes », on ne contracte pas : on dit <b lang="en">Yes, I am</b>, pas « Yes, I’m ».</p>
<p>Prononciation : <b lang="en">are</b> se dit « aa » (le r est muet en anglais britannique), et le s de <b lang="en">is</b> se prononce « z ».</p>`},
 {t:'Les emplois qui piègent un francophone',h:`<p>Beaucoup d’expressions où le français utilise <b>avoir</b> demandent <b lang="en">be</b> en anglais :</p>
${tb([[`J’ai douze ans`,`<b lang="en">I’m twelve.</b>`],[`J’ai faim / soif`,`<b lang="en">I’m hungry / thirsty.</b>`],[`J’ai chaud / froid`,`<b lang="en">I’m hot / cold.</b>`],[`J’ai peur`,`<b lang="en">I’m afraid / scared.</b>`]])}
<p>Autre piège : <b lang="en">it’s</b> (<b lang="en">it is</b>) et <b lang="en">its</b> (« son/sa » pour un objet ou un animal) se prononcent pareil mais s’écrivent différemment. Et le sujet est obligatoire : « Est fatigué » est impossible, il faut <b lang="en">He’s tired.</b></p>
<p>Exemple guidé : « Elle n’est pas dans la classe ; elle est malade. » → sujet <b lang="en">she</b> ; négation <b lang="en">isn’t</b> ; lieu <b lang="en">in the classroom</b> ; puis <b lang="en">she’s ill</b>. Résultat : <b lang="en">She isn’t in the classroom. She’s ill.</b></p>`}],
 try:{q:`Traduis : « Nous avons froid et nous ne sommes pas en retard. »`,a:`We’re cold and we aren’t late. (cold se dit avec be ; négation : aren’t.)`},
 adult:`Faites jouer une courte conversation de questions-réponses : « Are you tired? — Yes, I am. — Is the cat hungry? — No, it isn’t. » Corrigez particulièrement trois choses : « I have twelve years », l’oubli du sujet, et « Yes, I’m » à la place de « Yes, I am ».`,
 culture:{t:`Un verbe fait de plusieurs verbes`,h:`<p>Les formes <b lang="en">am, is, are, was, were, be</b> viennent de plusieurs verbes différents, qui ont fusionné au fil des siècles. Voilà pourquoi <b lang="en">be</b> ne ressemble à aucune règle : c’est un patchwork. Le français fait la même chose avec « être » : « je suis », « nous sommes », « j’étais », « je serai » ne se ressemblent pas.</p>`}},
'en6f':{
 deep:[{t:'Forme affirmative, négative, interrogative',h:`<p><b lang="en">Have got</b> exprime ce qu’on possède et la description physique. Il se conjugue comme suit :</p>
${tb([[`<b lang="en">I / you / we / they</b>`,`<b lang="en">have got</b> (<b lang="en">I’ve got</b>)`],[`<b lang="en">he / she / it</b>`,`<b lang="en">has got</b> (<b lang="en">she’s got</b>)`]])}
<p>Négation : <b lang="en">haven’t got</b> / <b lang="en">hasn’t got</b>. Question : on inverse. <b lang="en">Have you got a pet?</b> <b lang="en">Has she got a brother?</b> Réponses courtes : <b lang="en">Yes, I have.</b> / <b lang="en">No, she hasn’t.</b> On ne répète pas « got » dans la réponse.</p>
<p>Attention à la contraction : <b lang="en">she’s got</b> contient <b lang="en">has</b>, pas <b lang="en">is</b>. Comparer : <b lang="en">She’s got a cat</b> (a) et <b lang="en">She’s a teacher</b> (b, <b lang="en">is</b>). Dans (a), après <b lang="en">’s</b> vient <b lang="en">got</b> ou un participe ; dans (b), un nom ou un adjectif.</p>`},
 {t:'Décrire une personne et éviter les erreurs',h:`<p>On décrit les cheveux et les yeux avec <b lang="en">have got</b> : <b lang="en">He’s got short brown hair and blue eyes.</b> Le mot <b lang="en">hair</b> est généralement au singulier : <b lang="en">her hair is long</b>.</p>
<p>Mais l’âge, la faim et le froid se disent avec <b lang="en">be</b> (voir le chapitre sur BE) : <b lang="en">I’m twelve</b>, <b lang="en">I’m hungry</b>, <b lang="en">I’m cold</b>, jamais « I’ve got hungry ».</p>
<p>Exemple guidé. Phrase à traduire : « Mon amie Lina a un petit chien noir, mais elle n’a pas de chat. » On repère le sujet <b lang="en">Lina</b> (she), donc <b lang="en">has got</b>. On place l’adjectif devant le nom : <b lang="en">a small black dog</b>. Pour la négation : <b lang="en">she hasn’t got a cat</b>. Résultat : <b lang="en">My friend Lina has got a small black dog, but she hasn’t got a cat.</b></p>
${ul([`Pour un pluriel : <b lang="en">She’s got two brothers.</b>`,`Prononciation : <b lang="en">has</b> se dit « haz », <b lang="en">have</b> se dit « hav ».`])}`}],
 try:{q:`Mets à la forme négative : « He’s got a bike. » Puis pose la question correspondante.`,a:`He hasn’t got a bike. Has he got a bike? (on garde has ; on inverse sujet et has pour la question.)`},
 adult:`Jouez au portrait : pensez à un membre de la famille et décrivez-le par phrases courtes avec has got (« He’s got grey hair and glasses »). L’enfant devine, puis inverse les rôles. Vérifiez has avec he/she, et que got reste présent dans l’affirmative mais pas dans les réponses courtes.`,
 culture:{t:`Have got : une habitude britannique`,h:`<p>La forme <b lang="en">have got</b> est surtout courante en anglais britannique. Aux États-Unis, on préfère souvent <b lang="en">I have</b> et <b lang="en">Do you have a pet?</b>. Les deux versions sont correctes ; au collège, on t’apprend d’abord la forme britannique, qui est celle des manuels de la plupart des classes.</p>`}},
'en6g':{
 deep:[{t:'Jours et mois : toujours une majuscule',h:`<p>En français, jours et mois s’écrivent en minuscules. En anglais, ils prennent <b>toujours une majuscule</b> : <b lang="en">Monday, Tuesday, Wednesday, Thursday, Friday, Saturday, Sunday</b> ; <b lang="en">January, February, March…</b>. C’est aussi le cas des nationalités et des langues.</p>
<p>La semaine anglaise commence souvent un <b>lundi</b> au Royaume-Uni, mais le dimanche aux États-Unis dans beaucoup de calendriers.</p>
<p>Pièges de prononciation et d’orthographe :</p>
${ul([`<b lang="en">Wednesday</b> se dit « ouènzdé » : le premier <b lang="en">d</b> est muet, deux syllabes seulement.`,`<b lang="en">February</b> a un <b lang="en">r</b> avant le « u » dans l’écriture.`,`<b lang="en">Thursday</b> : th puis un son « eu » (comme dans « peur »).`,`<b lang="en">Tuesday</b> : « tiouzdé ».`])}`},
 {t:'Les dates et les nombres ordinaux',h:`<p>Pour dire une date, on utilise un <b lang="en">ordinal</b> : <b lang="en">first</b> (1er), <b lang="en">second</b>, <b lang="en">third</b>, <b lang="en">fourth</b>, <b lang="en">fifth</b>, <b lang="en">twelfth</b>, <b lang="en">twentieth</b>, <b lang="en">twenty-first</b>. Les trois premiers sont irréguliers ; ensuite on ajoute <b lang="en">-th</b> (sauf <b lang="en">fifth</b> et <b lang="en">twelfth</b> dont l’orthographe change).</p>
<p>À l’écrit : <b lang="en">1st, 2nd, 3rd, 4th…</b>. On peut dire <b lang="en">the fifth of May</b> ou <b lang="en">May the fifth</b>. On écrit <b lang="en">5th May</b> en Grande-Bretagne.</p>
<p>Piège : <b>04/05</b> signifie le 4 mai au Royaume-Uni mais le 5 avril aux États-Unis, où l’on met le mois d’abord. Écrire le mois en lettres évite la confusion.</p>
<p>Exemple guidé : « Mon anniversaire est le 23 octobre. » → <b lang="en">My birthday is on October the twenty-third</b> (ou <b lang="en">on the 23rd of October</b>). On utilise <b lang="en">on</b> devant une date, <b lang="en">in</b> devant un mois seul : <b lang="en">in October</b>.</p>`}],
 try:{q:`Comment dit-on « Mon anniversaire est le 2 mars » ? Écris-le avec l’ordinal.`,a:`My birthday is on March the second (ou on the 2nd of March). Majuscule à March, ordinal second, préposition on.`},
 adult:`Demandez à l’enfant de dire en anglais la date du jour, puis le jour de naissance de chaque membre de la famille. Insistez sur les ordinaux irréguliers (first, second, third, fifth, twelfth) et la majuscule des mois et des jours. Prononcez Wednesday avec lui : deux syllabes seulement.`,
 culture:{t:`Les dieux cachés dans la semaine`,h:`<p>Plusieurs jours anglais portent le nom de dieux de l’ancienne mythologie germanique : <b lang="en">Wednesday</b> (le jour de Wodan, ou Odin), <b lang="en">Thursday</b> (le jour de Thor), <b lang="en">Friday</b> (le jour de la déesse Frigg). <b lang="en">Saturday</b> vient de Saturne, un dieu romain, et <b lang="en">Sunday</b> et <b lang="en">Monday</b> viennent du Soleil et de la Lune. En français aussi, on retrouve Mars, Mercure ou Vénus dans les noms des jours.</p>`}},
'en6h':{
 deep:[{t:'Choisir le bon pronom sujet',h:`<p>Les pronoms sujets : <b lang="en">I, you, he, she, it, we, you, they</b>. Quelques repères pour ne pas se tromper :</p>
${ul([`<b lang="en">I</b> s’écrit toujours avec une majuscule, même au milieu d’une phrase.`,`<b lang="en">you</b> correspond à « tu » <b>et</b> à « vous » : il n’y a qu’une forme.`,`<b lang="en">he</b> pour un garçon ou un homme, <b lang="en">she</b> pour une fille ou une femme, <b lang="en">it</b> pour une chose, un animal ou une idée.`,`<b lang="en">they</b> pour plusieurs personnes ou choses, et le mot « on » ne se traduit pas toujours par <b lang="en">one</b> : on dit plutôt <b lang="en">we</b> ou <b lang="en">people</b>.`])}
<p>Le sujet est obligatoire : <b lang="en">It’s raining</b> (« il pleut »). <b lang="en">Is raining</b> est impossible.</p>
<p>Exemple guidé : « Tom et Léa jouent. » → deux personnes : <b lang="en">they play</b>. « Mon livre est sur la table. » → un objet : <b lang="en">it is on the table</b>. « Ma mère et moi » → <b lang="en">we</b>.</p>`},
 {t:'Les pronoms compléments',h:`<p>Quand le pronom n’est plus sujet mais complément (après un verbe ou une préposition), il change :</p>
${tb([[`<b lang="en">I → me</b>`,`<b lang="en">we → us</b>`],[`<b lang="en">you → you</b>`,`<b lang="en">you → you</b>`],[`<b lang="en">he → him</b>, <b lang="en">she → her</b>, <b lang="en">it → it</b>`,`<b lang="en">they → them</b>`]])}
<p>Exemples : <b lang="en">Look at me!</b> (et non « look at I »), <b lang="en">I like him</b>, <b lang="en">She helps us</b>. Après une préposition, on utilise toujours la forme complément : <b lang="en">with them</b>, <b lang="en">for her</b>.</p>
<p>Attention à ne pas confondre <b lang="en">her</b> (pronom complément : « elle/la/lui ») et <b lang="en">her</b> (possessif : « son/sa de elle »). Le sens dépend de la place : <b lang="en">I see her</b> (pronom) et <b lang="en">her bag</b> (possessif devant un nom).</p>
<p>Prononciation : <b lang="en">they</b> se dit « dè-i » avec le son /ð/ ; <b lang="en">she</b> avec « ch » (comme « chat ») et <b lang="en">he</b> avec un h soufflé.</p>`}],
 try:{q:`Remplace les mots soulignés par un pronom : « My mother and my father (…) love Tom (…). »`,a:`They love him. (« my mother and my father » = they ; Tom, complément = him.)`},
 adult:`Montrez une photo de famille. Demandez à l’enfant de dire en anglais qui est « he », « she » ou « they ». Puis faites des phrases très courtes avec des compléments (« I like him », « Look at them »). Évitez de traduire mot à mot : dans « You are kind », vous désigne une seule personne ou plusieurs.`,
 culture:{t:`Quand « thou » existait`,h:`<p>Il y a quelques siècles, l’anglais avait deux pronoms comme le français : <b lang="en">thou</b> (tu, familier) et <b lang="en">you</b> (vous, poli). On retrouve <b lang="en">thou</b> chez Shakespeare. Peu à peu, <b lang="en">you</b> a pris toute la place. C’est pourquoi l’anglais d’aujourd’hui n’a qu’une seule forme, et pourquoi il paraît parfois plus « familier » que le français.</p>`}},
'en6i':{
 deep:[{t:'Former le pluriel régulier',h:`<p>La règle générale : on ajoute <b lang="en">-s</b> au nom. Quelques cas particuliers :</p>
${tb([[`mots en <b lang="en">-s, -x, -ch, -sh, -z</b>`,`+ <b lang="en">-es</b> : <b lang="en">bus → buses</b>, <b lang="en">box → boxes</b>, <b lang="en">watch → watches</b>`],[`consonne + <b>y</b>`,`<b>y → ies</b> : <b lang="en">baby → babies</b>, <b lang="en">city → cities</b>`],[`voyelle + <b>y</b>`,`+ <b lang="en">s</b> : <b lang="en">boy → boys</b>, <b lang="en">day → days</b>`],[`mots en <b lang="en">-f / -fe</b>`,`<b lang="en">f → ves</b> : <b lang="en">knife → knives</b>, <b lang="en">leaf → leaves</b>`]])}
<p>Le <b lang="en">s</b> final se prononce de trois manières : « s » après un son sourd (<b lang="en">cats</b>), « z » après un son sonore ou une voyelle (<b lang="en">dogs, boys</b>), et « iz » après un son sifflant (<b lang="en">buses, watches</b>).</p>`},
 {t:'Les pluriels irréguliers à connaître par cœur',h:`<p>Une petite liste, très fréquente : </p>
${tb([[`<b lang="en">man → men</b>`,`<b lang="en">woman → women</b> (prononcer « wimine »)`],[`<b lang="en">child → children</b>`,`<b lang="en">person → people</b>`],[`<b lang="en">foot → feet</b>`,`<b lang="en">tooth → teeth</b>`],[`<b lang="en">mouse → mice</b>`,`<b lang="en">sheep, fish</b> : ne changent pas`]])}
<p>Le mot <b lang="en">people</b> est déjà un pluriel : on dit <b lang="en">people are</b>, et jamais « peoples are » pour parler de personnes en général. Les noms comme <b lang="en">glasses</b>, <b lang="en">trousers</b>, <b lang="en">jeans</b> ou <b lang="en">scissors</b> sont toujours au pluriel : <b lang="en">my jeans are blue</b>.</p>
<p>Exemple guidé : « Il y a trois enfants et deux souris dans la maison. » → on reconnaît deux irréguliers : <b lang="en">child → children</b>, <b lang="en">mouse → mice</b>. Résultat : <b lang="en">There are three children and two mice in the house.</b></p>
<p>Piège francophone : <b lang="en">news</b> se termine par un s mais reste singulier (<b lang="en">the news is good</b>).</p>`}],
 try:{q:`Mets au pluriel : « The baby has a knife and a box. »`,a:`The babies have knives and boxes. (baby → babies ; knife → knives ; box → boxes ; has devient have.)`},
 adult:`Faites une chasse aux pluriels dans la cuisine : une boîte, deux couteaux, trois bébés (sur une photo)… L’enfant donne le pluriel anglais à voix haute. Les irréguliers (men, women, children, feet, teeth, mice) peuvent être mimés ou dessinés pour mieux les retenir.`,
 culture:{t:`Pourquoi « children » ?`,h:`<p>En vieil anglais, plusieurs pluriels se formaient autrement qu’avec -s. <b lang="en">Children</b> garde la trace d’une ancienne terminaison en -n, comme <b lang="en">oxen</b> (les bœufs). Quant à <b lang="en">men</b>, <b lang="en">feet</b>, <b lang="en">teeth</b> et <b lang="en">mice</b>, leurs voyelles ont changé : ce sont des restes d’une très vieille manière de faire le pluriel.</p>`}},
'en6j':{
 deep:[{t:'CAN ne change jamais',h:`<p><b lang="en">Can</b> est un verbe modal : il sert à exprimer ce qu’on <b>sait faire</b> (capacité) ou ce qu’on a le <b>droit</b> de faire (permission). Il a trois règles simples :</p>
${ol([`Il ne prend <b>jamais de -s</b> : <b lang="en">she can swim</b>.`,`Il est suivi du verbe à l’infinitif <b>sans to</b> : <b lang="en">I can speak French</b>.`,`Il n’utilise pas <b lang="en">do/does</b> : négation <b lang="en">can’t</b> (ou <b lang="en">cannot</b>), question <b lang="en">Can you…?</b>`])}
${tb([[`<b lang="en">I can swim.</b>`,`Je sais nager.`],[`<b lang="en">He can’t play chess.</b>`,`Il ne sait pas jouer aux échecs.`],[`<b lang="en">Can you help me?</b>`,`Peux-tu m’aider ?`],[`<b lang="en">Yes, I can. / No, I can’t.</b>`,`Réponses courtes.`]])}
<p>Piège : « He can plays » ou « She can to dance » sont deux erreurs fréquentes. Dis plutôt <b lang="en">He can play</b> et <b lang="en">She can dance</b>.</p>`},
 {t:'Savoir, pouvoir, demander la permission',h:`<p>Le français a deux verbes (« savoir » et « pouvoir »), l’anglais n’en a qu’un : <b lang="en">can</b>.</p>
${ul([`Capacité : <b lang="en">I can ride a bike.</b> (Je sais faire du vélo.)`,`Possibilité ou permission : <b lang="en">You can sit here.</b> (Tu peux t’asseoir ici.)`,`Demande polie : <b lang="en">Can I open the window, please?</b> (Puis-je ouvrir la fenêtre ?)`])}
<p>Prononciation : dans une phrase positive, <b lang="en">can</b> est faible (« kn »), alors que <b lang="en">can’t</b> est fort et long (« caannt » en anglais britannique). C’est ce contraste qui permet d’entendre la différence entre <b lang="en">I can go</b> et <b lang="en">I can’t go</b>.</p>
<p>Exemple guidé : « Léo sait jouer de la guitare mais ne sait pas chanter. » → sujet <b lang="en">Léo</b> (he) ; deux verbes à l’infinitif sans to : <b lang="en">Léo can play the guitar, but he can’t sing.</b></p>
<p>On dit <b lang="en">play the guitar</b> (avec the) mais <b lang="en">play football</b> (sans the).</p>`}],
 try:{q:`Traduis : « Ma sœur sait nager mais elle ne sait pas faire du vélo. »`,a:`My sister can swim, but she can’t ride a bike. (can ne prend pas de s ; infinitif sans to.)`},
 adult:`Faites un petit sondage : « Can you swim? Can you ride a bike? Can you cook? » et notez les réponses courtes de chacun. Corrigez uniquement les erreurs de forme (can + s, can to). Pour la prononciation, faites répéter « I can go » puis « I can’t go » et demandez à l’enfant de dire laquelle il entend.`,
 culture:{t:`Le seul négatif en un mot`,h:`<p>La forme négative <b lang="en">cannot</b> s’écrit en un seul mot, alors que les autres verbes modaux s’écrivent en deux (<b lang="en">should not</b>, <b lang="en">must not</b>). On accepte aussi <b lang="en">can not</b>, mais il est rare. Dans la conversation, on utilise presque toujours la contraction <b lang="en">can’t</b>.</p>`}},
'en6k':{
 deep:[{t:'A ou AN : une question de son, pas de lettre',h:`<p>On choisit <b lang="en">a</b> ou <b lang="en">an</b> d’après le <b>son</b> qui commence le mot suivant, pas d’après la lettre :</p>
${tb([[`<b lang="en">an apple</b>, <b lang="en">an egg</b>`,`son voyelle`],[`<b lang="en">an hour</b>, <b lang="en">an honest man</b>`,`le <b lang="en">h</b> est muet : son voyelle`],[`<b lang="en">a university</b>, <b lang="en">a European</b>`,`début en « you » : son consonne`],[`<b lang="en">a house</b>, <b lang="en">a hat</b>`,`<b lang="en">h</b> prononcé : son consonne`]])}
<p><b lang="en">A</b> ou <b lang="en">an</b> s’emploie avec un nom <b>singulier dénombrable</b> quand on en parle pour la première fois, ou pour dire un métier : <b lang="en">She is a doctor.</b></p>
<p>L’article <b lang="en">the</b> sert quand le nom est déjà connu ou unique : <b lang="en">I have a dog. The dog is black.</b> (la première fois <b lang="en">a</b>, la seconde fois <b lang="en">the</b>). Il y a une seule lune et un seul soleil : <b lang="en">the moon</b>, <b lang="en">the sun</b>.</p>`},
 {t:'Quand ne pas mettre d’article',h:`<p>En français, on met presque toujours un article. En anglais, on n’en met pas dans plusieurs situations :</p>
${ul([`Pour parler d’une chose <b>en général</b> : <b lang="en">I love music.</b> (et non « the music »)`,`Devant les langues et la plupart des pays : <b lang="en">I speak English</b>, <b lang="en">I live in France</b>.`,`Dans certaines expressions : <b lang="en">go to school</b>, <b lang="en">at home</b>, <b lang="en">have breakfast</b>, <b lang="en">play football</b>.`,`Au pluriel indéfini : <b lang="en">I like dogs.</b> (et non « the dogs » si on parle des chiens en général).`])}
<p>Exemple guidé : « J’adore les pommes. Il y a une pomme sur la table. La pomme est rouge. » → premier énoncé général, sans article ; deuxième énoncé, première mention (<b lang="en">an</b> car son voyelle) ; troisième énoncé, mention connue (<b lang="en">the</b>). Résultat : <b lang="en">I love apples. There is an apple on the table. The apple is red.</b></p>`}],
 try:{q:`Complète avec a, an, the ou rien : « I have ___ umbrella. ___ umbrella is blue. I like ___ rain. »`,a:`I have an umbrella. The umbrella is blue. I like rain. (an : son voyelle ; the : déjà mentionné ; rien : sens général.)`},
 adult:`Écrivez au dos d’une enveloppe dix noms (apple, hour, university, egg, house, umbrella, hat, owl…) et demandez à l’enfant de les faire précéder de a ou an à l’oral. S’il hésite, redites la règle : on écoute le son, pas la lettre. Terminez par une courte histoire à deux phrases (« I see a… The … is… »).`,
 culture:{t:`Un tablier qui était un « napron »`,h:`<p>L’article <b lang="en">a</b> vient du mot <b lang="en">one</b> en vieil anglais : <b lang="en">an</b> veut dire à l’origine « un seul ». C’est un phénomène curieux : le mot « apron » (tablier) s’appelait <b lang="en">napron</b>, emprunté au français « naperon ». Les gens ont compris « a napron » comme « an apron », et le <b lang="en">n</b> a changé de place. Le même phénomène existe en français : on a dit « une orange » (de « norange »).</p>`}},
'en6l':{
 deep:[{t:'Le possesseur décide : his ou her ?',h:`<p>Les adjectifs possessifs : <b lang="en">my, your, his, her, its, our, your, their</b>. En français, « son » s’accorde avec la chose possédée (<b>son</b> frère, <b>sa</b> sœur). En anglais, c’est le <b lang="en">possesseur</b> qui décide :</p>
${tb([[`<b lang="en">Tom</b> et sa mère`,`<b lang="en">Tom and his mother</b>`],[`<b lang="en">Léa</b> et son père`,`<b lang="en">Léa and her father</b>`],[`le chien et sa niche`,`<b lang="en">the dog and its kennel</b>`],[`Tom et Léa, et leurs parents`,`<b lang="en">Tom and Léa and their parents</b>`]])}
<p>Les possessifs anglais ne changent pas devant un pluriel : <b lang="en">my books</b>, <b lang="en">our friends</b>. Et on n’ajoute pas d’article : <b lang="en">my bag</b> (jamais « the my bag »).</p>
<p>Piège : <b lang="en">its</b> (possessif, sans apostrophe) et <b lang="en">it’s</b> (<b lang="en">it is</b>) ne se confondent pas.</p>`},
 {t:'Le génitif : ’s',h:`<p>Pour dire que quelque chose appartient à quelqu’un, on ajoute <b lang="en">’s</b> au possesseur et on met le possesseur <b>en premier</b> : <b lang="en">Tom’s bag</b> (le sac de Tom), <b lang="en">my sister’s room</b> (la chambre de ma sœur). On ne dit pas « the bag of Tom » dans le langage courant.</p>
<p>Si le possesseur est un pluriel en -s, on ajoute seulement l’apostrophe : <b lang="en">the girls’ room</b> (la chambre des filles). Pour un pluriel irrégulier, on ajoute ’s : <b lang="en">the children’s toys</b>.</p>
<p>Pour demander à qui est un objet : <b lang="en">Whose bag is this? — It’s Tom’s.</b> ou <b lang="en">It’s his.</b></p>
<p>Exemple guidé : « Le chat de mon voisin aime sa balle. » → possesseur « my neighbour » + ’s ; « sa balle » : possesseur chat → <b lang="en">its</b>. Résultat : <b lang="en">My neighbour’s cat likes its ball.</b></p>`}],
 try:{q:`Traduis : « Léa cherche son livre et le cahier de ses frères. »`,a:`Léa is looking for her book and her brothers’ notebook. (her car Léa est une fille ; brothers’ car pluriel en -s ; on peut dire « notebook » au singulier si c’est un seul cahier commun.)`},
 adult:`Photographiez des objets de la maison et demandez « Whose is it? » (« It’s Dad’s », « It’s my sister’s »). Surveillez his/her : l’erreur la plus fréquente consiste à accorder avec l’objet comme en français. Faites aussi dire une phrase avec its pour un animal.`,
 culture:{t:`D’où vient l’apostrophe ?`,h:`<p>Le ’s du possessif était, en vieil anglais, une terminaison de cas, <b lang="en">-es</b>. Au fil du temps, la lettre <b lang="en">e</b> n’a plus été prononcée, et on l’a remplacée par une apostrophe. C’est donc un reste de grammaire ancienne, comme le <b lang="en">-s</b> du présent à la troisième personne.</p>`}},
'en6m':{
 deep:[{t:'Proche ou loin, un ou plusieurs',h:`<p>Ces quatre mots servent à montrer quelque chose. Ils se choisissent selon deux critères : la <b lang="en">distance</b> et le <b lang="en">nombre</b>.</p>
${tb([[``,`<b>un seul</b>`,`<b lang="en">plusieurs</b>`],[`<b lang="en">proche</b>`,`<b lang="en">this</b>`,`<b lang="en">these</b>`],[`<b lang="en">loin</b>`,`<b lang="en">that</b>`,`<b lang="en">those</b>`]])}
<p>Exemples : <b lang="en">This is my pen</b> (celui que je tiens), <b lang="en">That is your bag</b> (là-bas), <b lang="en">These are my friends</b>, <b lang="en">Those are birds</b>.</p>
<p>Ils peuvent aussi accompagner un nom : <b lang="en">this book</b>, <b lang="en">those boys</b>. Le nom doit être au même nombre : <b lang="en">these books</b>, jamais « these book ».</p>
<p>Au téléphone, on dit <b lang="en">Hello, this is Tom</b> (« ici Tom »), et non « I am Tom ».</p>`},
 {t:'Le piège de prononciation : this / these',h:`<p>La différence <b lang="en">this</b> /ðɪs/ (voyelle courte, « i » rapide) et <b lang="en">these</b> /ðiːz/ (voyelle longue, « iiiz ») est l’un des pièges les plus classiques pour un francophone. Si tu prononces les deux pareil, on ne comprend plus si tu parles d’un objet ou de plusieurs !</p>
<p>Astuce : <b lang="en">this</b> contient un « i » court et finit en « s » sourd ; <b lang="en">these</b> contient un « i » long et finit en « z » sonore. Entraîne-toi avec des paires : <b lang="en">this/these</b>, <b lang="en">that/those</b>.</p>
<p>Exemple guidé. Pour demander ce qu’est un objet : <b lang="en">What’s this?</b> (singulier) mais <b lang="en">What are these?</b> (pluriel). La réponse : <b lang="en">It’s a pen</b> / <b lang="en">They’re pens</b>.</p>
${ul([`<b lang="en">that</b> /ðæt/ : le a est ouvert, comme dans « chat » mais plus bref.`,`<b lang="en">those</b> /ðəʊz/ : « zoouz » avec un « z » final sonore.`])}`}],
 try:{q:`Complète : « ___ is my pencil (près de moi). ___ are your shoes (loin). »`,a:`This is my pencil. Those are your shoes. (this : proche et singulier ; those : loin et pluriel.)`},
 adult:`Placez des objets proches et éloignés dans la pièce et pointez-les en demandant « What’s this? » ou « What are those? ». L’enfant répond par une phrase complète (« Those are books »). Insistez sur la voyelle longue de these et sur le z final de those.`,
 culture:{t:`Ye Olde Shoppe : un faux « y »`,h:`<p>Sur certaines enseignes de pubs ou de boutiques, tu peux lire « Ye Olde Tea Shoppe ». Le « ye » ne se prononçait pas « yi » : c’était simplement le mot <b lang="en">the</b>. L’ancienne lettre <b lang="en">þ</b> (appelée « thorn »), qui représentait le son /θ/, ressemblait à un <b>y</b> dans l’écriture ancienne. Aujourd’hui encore, on prononce « the ».</p>`}},
'en6n':{
 deep:[{t:'There is / There are : présenter ce qui existe',h:`<p><b lang="en">There is</b> (singulier) et <b lang="en">there are</b> (pluriel) servent à dire qu’<b>il y a</b> quelque chose. Ils servent à présenter, à introduire un élément nouveau.</p>
${tb([[`<b lang="en">There is a cat on the sofa.</b>`,`Il y a un chat sur le canapé.`],[`<b lang="en">There are two cats in the garden.</b>`,`Il y a deux chats dans le jardin.`],[`<b lang="en">There isn’t a clock here.</b>`,`Il n’y a pas d’horloge ici.`],[`<b lang="en">Is there a park near here?</b>`,`Y a-t-il un parc près d’ici ?`],[`<b lang="en">Are there any shops?</b>`,`Y a-t-il des magasins ?`]])}
<p>Le verbe s’accorde avec ce qui <b lang="en">suit</b> : <b lang="en">There is</b> un chat, <b lang="en">there are</b> des chats. On dit souvent <b lang="en">there’s</b> à l’oral.</p>
<p>Piège : « il y a » ne se traduit <b>jamais</b> par « it has » ni « have ». Ne dis pas « In my room, it has a bed ».</p>`},
 {t:'Some, any, no : dire combien il y en a',h:`<p>On complète souvent <b lang="en">there is/are</b> avec <b lang="en">a</b>, <b lang="en">some</b>, <b lang="en">any</b>, <b lang="en">no</b> :</p>
${ul([`Affirmation : <b lang="en">There are some books.</b>`,`Négation : <b lang="en">There aren’t any books.</b> ou <b lang="en">There are no books.</b>`,`Question : <b lang="en">Are there any books?</b>`])}
<p>Exemple guidé. Décris ta chambre : <b lang="en">In my room, there is a bed and a desk. There are two posters on the wall. There isn’t a TV.</b> On commence par le lieu (<b lang="en">In my room</b>), puis <b lang="en">there is</b> + singulier, <b lang="en">there are</b> + pluriel, et on termine par une négation.</p>
<p>Ne confonds pas <b lang="en">there</b> (« là, il y a ») avec <b lang="en">their</b> (« leur ») et <b lang="en">they’re</b> (« ils sont ») : ces trois mots se prononcent à peu près de la même manière, mais n’ont pas la même fonction.</p>
<p>Prononciation : <b lang="en">there</b> se dit « dèr » avec le son /ð/ (langue entre les dents).</p>`}],
 try:{q:`Traduis : « Il y a un livre et deux stylos sur la table. Il n’y a pas de chaise. »`,a:`There is a book and two pens on the table. There isn’t a chair. (Avec « a book and two pens », on dit souvent aussi « There’s a book and two pens ».)`},
 adult:`Faites décrire une pièce de la maison avec « There is… / There are… ». Vous cachez un objet : l’enfant pose des questions (Is there a… ? Are there any… ?) pour le deviner. Corrigez surtout l’accord is/are et l’éviction de « it has ».`,
 culture:{t:`Trois mots qui se prononcent pareil`,h:`<p><b lang="en">There</b>, <b lang="en">their</b> et <b lang="en">they’re</b> sont des « homophones » : on les prononce de la même façon. Même les anglophones les confondent à l’écrit ! Voici l’astuce : <b lang="en">they’re</b> = they are, <b lang="en">their</b> = possessif (<b lang="en">their house</b>), <b lang="en">there</b> = lieu ou <b lang="en">there is/are</b>. Le français a aussi ses pièges : « ces / ses / c’est / s’est ».</p>`}},
'en6o':{
 deep:[{t:'Les prépositions de lieu essentielles',h:`<p>Une préposition de lieu dit <b lang="en">où</b> se trouve quelque chose. Voici les plus utiles :</p>
${tb([[`<b lang="en">in</b>`,`dans, à l’intérieur : <b lang="en">in the box</b>`],[`<b lang="en">on</b>`,`sur, en contact avec une surface : <b lang="en">on the table</b>`],[`<b lang="en">under</b>`,`sous : <b lang="en">under the bed</b>`],[`<b lang="en">next to</b>`,`à côté de : <b lang="en">next to the door</b>`],[`<b lang="en">between</b>`,`entre (deux) : <b lang="en">between the chair and the desk</b>`],[`<b lang="en">behind</b> / <b lang="en">in front of</b>`,`derrière / devant`],[`<b lang="en">opposite</b>`,`en face de : <b lang="en">opposite the school</b>`],[`<b lang="en">near</b>`,`près de`]])}
<p>Attention : <b lang="en">in front of</b> et <b lang="en">opposite</b> ne sont pas synonymes. <b lang="en">The bus stop is in front of the school</b> : il est juste devant, du même côté. <b lang="en">The bus stop is opposite the school</b> : il est de l’autre côté de la rue.</p>`},
 {t:'Répondre à « Where is… ? »',h:`<p>Pour demander où se trouve quelque chose : <b lang="en">Where is my pen?</b> (singulier) / <b lang="en">Where are my keys?</b> (pluriel). On répond avec <b lang="en">It’s</b> / <b lang="en">They’re</b> et une préposition : <b lang="en">It’s in your bag.</b> <b lang="en">They’re on the table.</b></p>
<p>Plusieurs prépositions se traduisent différemment selon le contexte :</p>
${ul([`<b lang="en">in the picture</b> (dans l’image), <b lang="en">on the wall</b> (sur le mur : accroché), <b lang="en">at the bus stop</b> (à l’arrêt de bus, un point précis).`,`<b lang="en">on the left</b> / <b lang="en">on the right</b> : à gauche / à droite.`,`<b lang="en">in the street</b> mais <b lang="en">on the road</b> pour une route.`])}
<p>Exemple guidé. Phrase à décrire : un chat est caché sous la table, entre deux chaises. → <b lang="en">The cat is under the table, between the two chairs.</b> Le lieu est introduit par une préposition ; on précise ensuite la position avec une deuxième préposition.</p>
<p>Prononciation : <b lang="en">between</b> se dit « bitouine » avec un « i » long, <b lang="en">behind</b> « bihaïnd ». Le <b lang="en">h</b> de <b lang="en">behind</b> se prononce vraiment.</p>`}],
 try:{q:`Où est le chat ? « Le chat est sur la chaise, à côté du sac, devant la fenêtre. »`,a:`The cat is on the chair, next to the bag, in front of the window.`},
 adult:`Cachez un petit objet dans la pièce et laissez l’enfant le chercher en posant des questions (Is it under…? Is it next to…?). Il répond ensuite avec une phrase complète. Faites bien distinguer in front of et opposite, qui se traduisent tous deux par « devant » dans de nombreuses phrases françaises.`,
 culture:{t:`Rouler à gauche`,h:`<p>Au Royaume-Uni, on roule à gauche : à Londres, quand tu traverses, il faut regarder à droite en premier. Beaucoup de passages piétons portent d’ailleurs l’inscription <b lang="en">Look right</b> ou <b lang="en">Look left</b> sur la chaussée, pour aider les touristes. Aux États-Unis, comme en France, on roule à droite.</p>`}},
'en6p':{
 deep:[{t:'AT, ON, IN : un schéma pour le temps',h:`<p>En français, on dit « à » ou « en » pour presque tout. En anglais, on choisit entre trois prépositions selon la « taille » du moment :</p>
${tb([[`<b lang="en">at</b>`,`un point précis : <b lang="en">at 7 o’clock</b>, <b lang="en">at noon</b>, <b lang="en">at night</b>, <b lang="en">at the weekend</b>`],[`<b lang="en">on</b>`,`un jour ou une date : <b lang="en">on Monday</b>, <b lang="en">on 5th May</b>, <b lang="en">on my birthday</b>`],[`<b lang="en">in</b>`,`une période plus longue : <b lang="en">in May</b>, <b lang="en">in summer</b>, <b lang="en">in 2026</b>, <b lang="en">in the morning</b>`]])}
<p>Quand un jour est précisé avec un moment de la journée, on garde <b lang="en">on</b> : <b lang="en">on Monday morning</b>, <b lang="en">on Friday evening</b>. Mais sans jour : <b lang="en">in the morning</b>, <b lang="en">in the afternoon</b>, <b lang="en">in the evening</b>. L’exception à retenir : <b lang="en">at night</b>.</p>
<p>On n’emploie aucune préposition devant <b lang="en">next</b>, <b lang="en">last</b>, <b lang="en">every</b>, <b lang="en">this</b> : <b lang="en">next Monday</b>, <b lang="en">every day</b>, <b lang="en">last summer</b>.</p>`},
 {t:'Les erreurs typiques et un exemple guidé',h:`<p>Les francophones disent souvent « in Monday » ou « at May ». Une astuce : pense à un entonnoir. <b lang="en">In</b> est large (années, saisons, mois), <b lang="en">on</b> se resserre sur le jour, et <b lang="en">at</b> pointe l’heure exacte.</p>
<p>Exemple guidé : « Le samedi matin, je me lève à huit heures, et en été, je me couche tard. »</p>
${ol([`« Le samedi matin » : un jour précis avec un moment → <b lang="en">on Saturday morning</b>.`,`« à huit heures » : heure exacte → <b lang="en">at eight</b>.`,`« en été » : saison → <b lang="en">in summer</b>.`])}
<p>Résultat : <b lang="en">On Saturday morning, I get up at eight, and in summer, I go to bed late.</b></p>
<p>Prononciation : <b lang="en">weekend</b> est accentué sur le premier mot (WEEKend), alors que <b lang="en">afternoon</b> est accentué sur la dernière syllabe (afterNOON).</p>
<p>Attention au mot <b lang="en">Christmas</b> : on dit <b lang="en">at Christmas</b> (pour la période) mais <b lang="en">on Christmas Day</b> (pour le jour).</p>`}],
 try:{q:`Complète avec at, on ou in : « I play tennis ___ Tuesday, ___ 4 o’clock, ___ winter. »`,a:`I play tennis on Tuesday, at 4 o’clock, in winter. (jour → on ; heure → at ; saison → in.)`},
 adult:`Créez un petit emploi du temps de la famille et demandez à l’enfant de le décrire en anglais : « On Saturday, we go to the market at nine. In summer, we… ». Repérez surtout les erreurs sur on/in avec les jours, et sur la phrase at night.`,
 culture:{t:`L’heure du monde est née à Greenwich`,h:`<p>En 1884, une conférence internationale à Washington a choisi le méridien de <b lang="en">Greenwich</b>, près de Londres, comme référence pour mesurer les longitudes et les fuseaux horaires. C’est l’origine du <b lang="en">GMT</b> (Greenwich Mean Time), l’heure de référence qui a longtemps servi de base à l’heure du monde.</p>`}},
'en6q':{
 deep:[{t:'Quand et comment l’utiliser',h:`<p>Le <b>présent simple</b> (<b lang="en">present simple</b>) exprime les habitudes, les faits vrais en général et les emplois du temps : <b lang="en">I play football on Saturdays.</b> <b lang="en">The sun rises in the east.</b></p>
<p>À toutes les personnes, le verbe garde sa forme de base, <b>sauf à he/she/it</b>, où on ajoute <b lang="en">-s</b> :</p>
${tb([[`<b lang="en">I play</b>`,`<b lang="en">he plays</b>`],[`<b lang="en">you work</b>`,`<b lang="en">she works</b>`],[`<b lang="en">we study</b>`,`<b lang="en">he studies</b> (y → ies)`],[`<b lang="en">they watch</b>`,`<b lang="en">it watches</b> (+ es)`],[`<b lang="en">I have</b>`,`<b lang="en">she has</b>`],[`<b lang="en">I go</b>`,`<b lang="en">he goes</b>`]])}
<p>Le <b lang="en">s</b> final se prononce « s » (<b lang="en">works</b>), « z » (<b lang="en">plays</b>) ou « iz » (<b lang="en">watches</b>). Entraîne-toi : ces trois sons sont une aide pour se faire comprendre.</p>`},
 {t:'La négation et la question, étape par étape',h:`<p>Avec ce temps, on utilise <b lang="en">do</b> comme auxiliaire :</p>
${tb([[`<b lang="en">I don’t like fish.</b>`,`<b lang="en">She doesn’t like fish.</b>`],[`<b lang="en">Do you play tennis?</b>`,`<b lang="en">Does he play tennis?</b>`],[`<b lang="en">Yes, I do.</b> / <b lang="en">No, I don’t.</b>`,`<b lang="en">Yes, he does.</b> / <b lang="en">No, he doesn’t.</b>`]])}
<p>Règle d’or : avec <b lang="en">doesn’t</b> et <b lang="en">does</b>, le verbe principal <b>reprend sa forme de base</b> : le -s est « parti » sur <b lang="en">does</b>. On écrit donc <b lang="en">She doesn’t play</b>, jamais « She doesn’t plays ».</p>
<p>Exemple guidé : « Mon frère ne mange pas de viande. »</p>
${ol([`Sujet <b lang="en">my brother</b> = <b lang="en">he</b> → <b lang="en">doesn’t</b>.`,`Verbe <b lang="en">eat</b> à la forme de base.`,`<b lang="en">My brother doesn’t eat meat.</b>`])}
<p>Ne confonds pas ce temps avec <b lang="en">be</b> : on ne dit pas « I am play ». Un verbe d’action suit <b lang="en">do</b>, le verbe <b lang="en">be</b> s’utilise tout seul.</p>`}],
 try:{q:`Mets à la forme interrogative : « Your sister studies English. » Puis réponds par oui, avec une réponse courte.`,a:`Does your sister study English? — Yes, she does. (study sans s après does ; réponse courte avec does.)`},
 adult:`Interrogez votre enfant sur ses habitudes : « Do you get up at 7? Does your brother play football? ». Il répond par une phrase complète. Surveillez deux erreurs : l’oubli du s à he/she/it, et l’ajout du s après doesn’t. Faites-lui ensuite poser vos questions.`,
 culture:{t:`Un seul s qui reste`,h:`<p>En ancien français, comme en latin, chaque personne avait sa terminaison. En anglais, au présent, seule la troisième personne du singulier en a conservé une : le <b lang="en">-s</b>. C’est l’un des systèmes de conjugaison les plus simples d’Europe. Il y a six formes différentes en français pour « jouer » au présent (joue, joues, jouons, jouez, jouent…), contre deux seulement pour <b lang="en">play</b> (play, plays).</p>`}},
'en6r':{
 deep:[{t:'L’échelle des goûts',h:`<p>Pour exprimer les goûts, on utilise une échelle de verbes, du plus fort au plus faible :</p>
${tb([[`<b lang="en">I love…</b>`,`J’adore…`],[`<b lang="en">I like…</b>`,`J’aime bien…`],[`<b lang="en">I don’t mind…</b>`,`Ça ne me dérange pas…`],[`<b lang="en">I don’t like…</b>`,`Je n’aime pas…`],[`<b lang="en">I hate…</b>`,`Je déteste…`]])}
<p>Après ces verbes, on peut utiliser un <b>nom</b> (<b lang="en">I like pizza</b>), un <b>verbe en -ing</b> (<b lang="en">I like swimming</b>) ou un <b>pronom complément</b> (<b lang="en">I like it</b>, <b lang="en">I love them</b>).</p>
<p>Piège : en français, on dit « j’aime <b>le</b> chocolat » avec l’article défini. En anglais, pour un goût général, on n’en met pas : <b lang="en">I like chocolate</b>, <b lang="en">I hate maths</b>, <b lang="en">she loves cats</b>.</p>`},
 {t:'Poser la question et répondre',h:`<p>Pour demander les goûts : <b lang="en">Do you like football?</b> (réponse courte : <b lang="en">Yes, I do.</b> / <b lang="en">No, I don’t.</b>). Avec une troisième personne, c’est <b lang="en">does</b> : <b lang="en">Does she like cats?</b> — <b lang="en">Yes, she does.</b></p>
<p>Pour demander « qu’est-ce que tu aimes ? » : <b lang="en">What do you like?</b>, et « quel est ton sport préféré ? » : <b lang="en">What’s your favourite sport?</b>.</p>
<p>Exemple guidé : « Léo adore le foot, mais il n’aime pas nager. » → <b lang="en">Léo</b> = he, donc <b lang="en">loves</b> avec un s ; la négation <b lang="en">doesn’t like</b> avec un verbe en -ing : <b lang="en">Léo loves football, but he doesn’t like swimming.</b></p>
${ul([`Ne dis pas « I am liking » : le verbe <b lang="en">like</b> se met au présent simple.`,`Ne dis pas « I like to the music » : pas de préposition.`])}
<p>Prononciation : <b lang="en">hate</b> commence par un h soufflé, <b lang="en">love</b> se dit « lave » (comme dans « lave-vaisselle » mais avec un v), <b lang="en">like</b> « laïk ».</p>`}],
 try:{q:`Traduis : « Ma sœur adore les chats mais elle déteste le poisson. »`,a:`My sister loves cats but she hates fish. (pas d’article pour un goût général ; loves, hates avec s.)`},
 adult:`Jouez à « Truth or lie » : l’enfant dit trois phrases sur ses goûts (« I love spinach »), l’adulte devine laquelle est fausse. Corrigez l’article en trop (« I love the chocolate ») et l’oubli du s à he/she. Un petit sondage dans la famille avec Does he/she like… ? rend l’exercice vivant.`,
 culture:{t:`Un logo devenu mondial`,h:`<p>Le logo <b lang="en">I ♥ NY</b> a été dessiné en 1977 par le graphiste Milton Glaser pour une campagne de promotion de l’État de New York. Il est devenu l’un des logos les plus copiés au monde : on le retrouve sur des tasses et des tee-shirts. Il illustre bien le verbe <b lang="en">love</b> : le cœur remplace le mot !</p>`}},
'en6s':{
 deep:[{t:'Le vocabulaire de la routine',h:`<p>Voici les expressions de la journée, avec les verbes à retenir. Beaucoup de verbes ne se traduisent pas mot à mot :</p>
${tb([[`<b lang="en">get up</b>`,`se lever`],[`<b lang="en">have breakfast / lunch / dinner</b>`,`prendre son petit-déjeuner / déjeuner / dîner`],[`<b lang="en">brush my teeth</b>`,`me brosser les dents`],[`<b lang="en">have a shower</b>`,`prendre une douche`],[`<b lang="en">go to school</b>`,`aller à l’école`],[`<b lang="en">do my homework</b>`,`faire mes devoirs`],[`<b lang="en">go to bed</b>`,`aller se coucher`]])}
<p>Piège : on dit <b lang="en">have breakfast</b>, pas « take breakfast », et <b lang="en">do my homework</b>, pas « make my homework ». <b lang="en">Do</b> s’utilise pour les tâches, <b lang="en">make</b> pour fabriquer quelque chose (<b lang="en">make a cake</b>).</p>
<p>Pour l’ordre : <b lang="en">first, then, after that, finally</b>.</p>`},
 {t:'Raconter sa journée, à toutes les personnes',h:`<p>Pour raconter une routine, on utilise le présent simple avec des mots de liaison et des heures :</p>
<p><b lang="en">I get up at seven. First, I brush my teeth. Then I have breakfast. After that, I go to school. In the evening, I do my homework and I go to bed at nine.</b></p>
<p>Pour parler d’une autre personne, on ajoute le <b lang="en">s</b> : <b lang="en">She gets up at seven. She goes to school by bus. She does her homework.</b> Les verbes <b lang="en">go</b>, <b lang="en">do</b> prennent <b lang="en">-es</b>, et <b lang="en">have</b> devient <b lang="en">has</b>.</p>
<p>Exemple guidé : « Tom prend son petit-déjeuner à sept heures et demie. » → sujet <b lang="en">Tom</b> = he, verbe <b lang="en">have</b> → <b lang="en">has</b>. Heure : <b lang="en">at half past seven</b>. Résultat : <b lang="en">Tom has breakfast at half past seven.</b></p>
${ul([`Pour la fréquence, place <b lang="en">always</b>, <b lang="en">usually</b>, <b lang="en">never</b> devant le verbe : <b lang="en">I usually walk to school</b>.`,`Prononciation : <b lang="en">usually</b> se dit « iouj-ouelli » ; <b lang="en">breakfast</b> « brek-fest ».`])}`}],
 try:{q:`Traduis : « Elle se lève à sept heures et fait ses devoirs le soir. »`,a:`She gets up at seven and does her homework in the evening. (gets, does : s ou es à she ; in the evening.)`},
 adult:`Demandez à votre enfant de décrire sa journée d’hier ou celle d’un autre membre de la famille avec first, then, after that. Aidez-le uniquement sur les verbes (get up, have breakfast, do homework). Contrôlez le s de he/she et les expressions on/at/in du chapitre précédent.`,
 culture:{t:`Breakfast : « rompre le jeûne »`,h:`<p>Le mot <b lang="en">breakfast</b> est formé de <b lang="en">break</b> (rompre) et <b lang="en">fast</b> (jeûne) : c’est le repas qui rompt le jeûne de la nuit. Le français « petit déjeuner » dit la même chose : « dé-jeûner » signifie à l’origine cesser de jeûner. Le « full English breakfast » traditionnel comprend des œufs, du bacon, des saucisses, des haricots à la sauce tomate et des toasts.</p>`}},
'en6t':{
 deep:[{t:'Les deux façons de dire l’heure',h:`<p>Il y a une façon « pile » et une façon « avec les minutes » :</p>
${tb([[`<b lang="en">It’s seven o’clock.</b>`,`Il est sept heures (pile).`],[`<b lang="en">It’s five past seven.</b>`,`Sept heures cinq.`],[`<b lang="en">It’s quarter past seven.</b>`,`Sept heures et quart.`],[`<b lang="en">It’s half past seven.</b>`,`Sept heures et demie.`],[`<b lang="en">It’s quarter to eight.</b>`,`Huit heures moins le quart.`],[`<b lang="en">It’s twenty to eight.</b>`,`Huit heures moins vingt.`]])}
<p>La règle : jusqu’à 30 minutes, on utilise <b lang="en">past</b> (« après ») avec l’heure qui vient de passer ; après 30 minutes, on utilise <b lang="en">to</b> (« avant ») avec l’heure qui vient. On peut aussi dire simplement <b lang="en">It’s seven forty</b> (7 h 40).</p>
<p>Pour demander : <b lang="en">What time is it?</b> ou <b lang="en">What’s the time?</b></p>`},
 {t:'Pièges et exemple guidé',h:`<p>Les pièges habituels :</p>
${ul([`<b lang="en">half past seven</b> = 7 h 30, pas 6 h 30 : ne confonds pas avec <b lang="en">half to</b>, qui n’existe pas.`,`Pour 12 heures, on dit <b lang="en">noon</b> (midi) et <b lang="en">midnight</b> (minuit).`,`<b lang="en">a.m.</b> = avant midi, <b lang="en">p.m.</b> = après midi : <b lang="en">7 p.m.</b> = 19 h.`,`Pour situer une action, on utilise <b lang="en">at</b> : <b lang="en">The film starts at eight.</b>`])}
<p>Prononciation : <b lang="en">quarter</b> se dit « kwoteu » (le r final est muet en anglais britannique), <b lang="en">o’clock</b> « eu-clok » : c’est une contraction de <b lang="en">of the clock</b>. <b lang="en">Twenty</b> se dit « touenti ».</p>
<p>Exemple guidé : « Le cours commence à huit heures vingt-cinq et finit à neuf heures moins le quart. »</p>
${ol([`8 h 25 : 25 minutes passées → <b lang="en">twenty-five past eight</b>.`,`8 h 45 : après 30 minutes, on compte à rebours → <b lang="en">quarter to nine</b>.`])}
<p>Résultat : <b lang="en">The lesson starts at twenty-five past eight and finishes at quarter to nine.</b></p>`}],
 try:{q:`Écris en toutes lettres : 4 h 15, 4 h 30, 4 h 45.`,a:`quarter past four ; half past four ; quarter to five.`},
 adult:`Placez une horloge à aiguilles sur la table et déplacez les aiguilles : l’enfant dit l’heure en anglais de deux façons (It’s twenty past three / It’s three twenty). Insistez sur la direction : past après l’heure, to avant l’heure suivante, et sur la prononciation de quarter.`,
 culture:{t:`Big Ben n’est pas la tour`,h:`<p>Beaucoup de gens appellent <b lang="en">Big Ben</b> la tour de l’horloge du Parlement britannique, à Londres. En réalité, <b lang="en">Big Ben</b> est le nom de la grosse cloche à l’intérieur. La tour, elle, porte le nom d’<b lang="en">Elizabeth Tower</b> depuis 2012. Elle abrite l’une des horloges à quatre cadrans les plus célèbres du monde.</p>`}},
'en6u':{
 deep:[{t:'Décrire le temps qu’il fait',h:`<p>Pour dire le temps, on utilise le sujet <b lang="en">it</b> (obligatoire !) avec <b lang="en">be</b> et un adjectif : <b lang="en">It’s sunny.</b> <b lang="en">It’s cloudy.</b> <b lang="en">It’s windy.</b> <b lang="en">It’s foggy.</b> Avec un verbe : <b lang="en">It’s raining.</b> <b lang="en">It’s snowing.</b></p>
${tb([[`<b lang="en">sunny / cloudy / windy / foggy</b>`,`ensoleillé / nuageux / venteux / brumeux`],[`<b lang="en">rainy / snowy</b>`,`pluvieux / neigeux`],[`<b lang="en">hot / warm / cool / cold / freezing</b>`,`très chaud / chaud / frais / froid / glacial`]])}
<p>Pour demander : <b lang="en">What’s the weather like?</b> Le mot <b lang="en">weather</b> est <b>indénombrable</b> : on ne dit pas « a weather » ni « weathers ». Pour parler des degrés : <b lang="en">It’s twenty degrees.</b></p>`},
 {t:'Les saisons, les degrés et les prononciations',h:`<p>Les quatre saisons : <b lang="en">spring, summer, autumn, winter</b>. L’automne se dit <b lang="en">autumn</b> au Royaume-Uni et <b lang="en">fall</b> aux États-Unis. On utilise <b lang="en">in</b> : <b lang="en">in winter</b>, <b lang="en">in the spring</b> est aussi correct.</p>
<p>Prononciation : <b lang="en">weather</b> /ˈweðə/ a le son /ð/ au milieu (langue entre les dents). Ne le confonds pas avec <b lang="en">whether</b> (« si »), prononcé de la même façon, ni avec <b lang="en">wet</b> (mouillé). <b lang="en">Rain</b> se dit « rèïn », <b lang="en">snow</b> « snoou ».</p>
<p>Dans les pays anglophones, la température se donne en degrés Celsius au Royaume-Uni, mais en degrés Fahrenheit aux États-Unis : 32 °F correspondent à 0 °C.</p>
<p>Exemple guidé : « En été, il fait chaud et il ne pleut pas souvent. » → <b lang="en">In summer, it’s hot and it doesn’t rain often.</b> On répète le sujet <b lang="en">it</b> devant chaque verbe. Pour la négation : <b lang="en">doesn’t</b> (présent simple, troisième personne).</p>`}],
 try:{q:`Traduis : « Aujourd’hui, il pleut et il y a du vent. »`,a:`Today it’s raining and it’s windy. (le sujet it est obligatoire ; windy est un adjectif avec be.)`},
 adult:`Regardez ensemble la météo du lendemain (sur un site ou à la télévision) et demandez à l’enfant de la résumer en anglais en deux ou trois phrases. Vérifiez le sujet it, l’absence de s à weather, et l’emploi de be (It’s cold) plutôt que have.`,
 culture:{t:`Le sujet favori des Britanniques`,h:`<p>Parler de la météo est considéré comme le sujet de conversation le plus courant au Royaume-Uni. C’est une façon polie de commencer une discussion avec quelqu’un qu’on ne connaît pas : <b lang="en">Nice day, isn’t it?</b> L’expression <b lang="en">It’s raining cats and dogs</b> signifie qu’il pleut très fort ; on ne la traduit jamais mot à mot.</p>`}},
'en6v':{
 deep:[{t:'House ou home ? Les pièces de la maison',h:`<p>En anglais, <b lang="en">house</b> désigne le bâtiment, alors que <b lang="en">home</b> désigne le « chez-soi », l’endroit où l’on vit. On dit <b lang="en">I’m at home</b> (sans article), jamais « at the home ». On dit <b lang="en">flat</b> au Royaume-Uni et <b lang="en">apartment</b> aux États-Unis.</p>
${tb([[`<b lang="en">kitchen</b>`,`cuisine`],[`<b lang="en">living room</b>`,`salon`],[`<b lang="en">bedroom</b>`,`chambre`],[`<b lang="en">bathroom</b>`,`salle de bains`],[`<b lang="en">toilet</b>`,`toilettes`],[`<b lang="en">garden</b>`,`jardin`],[`<b lang="en">hall</b>`,`entrée`]])}
<p>Piège : <b lang="en">bathroom</b> contient <b lang="en">bath</b> (baignoire), mais pas forcément de toilettes. <b lang="en">Toilet</b> n’est pas un mot grossier ; aux États-Unis on dit souvent <b lang="en">restroom</b> pour un lieu public.</p>`},
 {t:'Meubles, prépositions et description',h:`<p>Meubles : <b lang="en">bed, sofa, table, chair, desk, wardrobe</b> (armoire à vêtements), <b lang="en">cupboard</b> (placard), <b lang="en">shelf</b> (étagère, pluriel <b lang="en">shelves</b>), <b lang="en">lamp, mirror</b>.</p>
<p>Pour décrire une pièce, on utilise <b lang="en">there is / there are</b> et les prépositions de lieu : <b lang="en">In my bedroom, there is a bed next to the window. There are two shelves above the desk.</b></p>
<p>Prononciation : <b lang="en">kitchen</b> « kitchine », <b lang="en">bedroom</b> « bèdroum » (avec un « oo » long), <b lang="en">wardrobe</b> « ouôdroub ». Le mot <b lang="en">garage</b> se prononce « garaage » ou « garidj » selon la région.</p>
<p>Exemple guidé : « Ma maison a un rez-de-chaussée et un étage. » → Au Royaume-Uni, le rez-de-chaussée s’appelle le <b lang="en">ground floor</b> et l’étage <b lang="en">first floor</b>. Résultat : <b lang="en">My house has a ground floor and a first floor.</b> Aux États-Unis, <b lang="en">first floor</b> désigne le rez-de-chaussée !</p>
<p>Ne dis pas « chaise longue » ni « chair » pour une armoire ; apprends chaque nom avec une image.</p>`}],
 try:{q:`Traduis : « Il y a un canapé dans le salon et une lampe à côté de la fenêtre. »`,a:`There is a sofa in the living room and a lamp next to the window.`},
 adult:`Faites une visite guidée de votre logement en anglais : l’enfant nomme chaque pièce et décrit trois objets avec there is/are et des prépositions. Faites-lui dessiner sa chambre idéale, puis l’expliquer. Vérifiez house/home et le pluriel irrégulier shelves.`,
 culture:{t:`Rez-de-chaussée ou premier étage ?`,h:`<p>Au Royaume-Uni, le rez-de-chaussée est le <b lang="en">ground floor</b> et le premier étage est le <b lang="en">first floor</b> : c’est comme en France. Aux États-Unis, le rez-de-chaussée est le <b lang="en">first floor</b>. Dans un ascenseur américain, le bouton 1 mène donc au niveau de la rue. C’est un détail qui surprend de nombreux voyageurs.</p>`}},
'en6w':{
 deep:[{t:'Les vêtements et les noms toujours au pluriel',h:`<p>Vocabulaire de base : <b lang="en">T-shirt, shirt, jumper</b> (pull), <b lang="en">hoodie, coat, jacket, dress, skirt, trousers, jeans, shorts, socks, shoes, trainers</b> (baskets), <b lang="en">hat, cap, scarf, gloves</b>.</p>
<p>Les vêtements à deux jambes ou à deux parties sont <b>toujours au pluriel</b> en anglais : <b lang="en">trousers, jeans, shorts, pyjamas, glasses, scissors</b>. On dit <b lang="en">My jeans are blue</b> (are, pas is). Pour parler d’un seul, on utilise <b lang="en">a pair of</b> : <b lang="en">a pair of jeans</b>, <b lang="en">two pairs of socks</b>.</p>
<p>Prononciation : <b lang="en">clothes</b> se dit « klôouz » (le th ne se prononce presque pas) ; ne le confonds pas avec <b lang="en">cloths</b> (des chiffons). <b lang="en">Shoes</b> se dit « chouz », <b lang="en">jeans</b> « djînz ».</p>`},
 {t:'Porter, essayer, et décrire une tenue',h:`<p>Le verbe <b lang="en">wear</b> signifie « porter » : <b lang="en">She is wearing a red dress today.</b> Avec le présent en -ing, on décrit ce que la personne a sur elle en ce moment. Le verbe <b lang="en">put on</b> exprime l’action d’enfiler : <b lang="en">Put on your coat!</b>. Les deux ne sont pas interchangeables.</p>
<p>Faux ami : <b lang="en">costume</b> en anglais signifie « déguisement » ou « tenue de théâtre ». Un « costume d’homme » se dit <b lang="en">a suit</b>. Autre piège : un « pull » se dit <b lang="en">a jumper</b> (ou <b lang="en">sweater</b>), pas « a pull ».</p>
<p>Exemple guidé : « Aujourd’hui, Léa porte un jean bleu, un pull vert et des baskets blanches. »</p>
${ol([`Verbe : <b lang="en">is wearing</b> (action en cours).`,`Adjectifs avant le nom : <b lang="en">blue jeans</b>, <b lang="en">a green jumper</b>, <b lang="en">white trainers</b>.`])}
<p>Résultat : <b lang="en">Today Léa is wearing blue jeans, a green jumper and white trainers.</b> Pas de s à blue ni à white.</p>`}],
 try:{q:`Corrige l’erreur : « My trousers is black and my jean are new. »`,a:`My trousers are black and my jeans are new. (les deux noms sont toujours pluriels : are ; jean → jeans.)`},
 adult:`Jouez à « What am I wearing? » : décrivez votre tenue pendant que l’enfant ferme les yeux et devine ; puis inversez les rôles. Corrigez l’accord (trousers are) et le piège costume/suit. Prononcez clothes lentement avec lui.`,
 culture:{t:`Les jeans viennent de Gênes et de Nîmes`,h:`<p>Le mot <b lang="en">jeans</b> viendrait de <b lang="en">Gênes</b> (en anglais <b lang="en">Genoa</b>), ville d’Italie où l’on fabriquait une toile solide. Le mot <b lang="en">denim</b> vient quant à lui de l’expression française « serge de Nîmes ». Cette toile a été utilisée par des ouvriers avant de devenir un vêtement à la mode. Deux villes d’Europe, Gênes et Nîmes, ont donc donné leur nom à un vêtement mondial.</p>`}},
'en6x':{
 deep:[{t:'Aliments, boissons, repas',h:`<p>Les repas : <b lang="en">breakfast</b> (matin), <b lang="en">lunch</b> (midi), <b lang="en">dinner</b> ou <b lang="en">tea</b>/<b lang="en">supper</b> (soir, selon les familles). On dit <b lang="en">have lunch</b> (sans article).</p>
${tb([[`<b lang="en">bread, butter, cheese, rice, pasta</b>`,`pain, beurre, fromage, riz, pâtes`],[`<b lang="en">chicken, fish, egg</b>`,`poulet, poisson, œuf`],[`<b lang="en">apple, banana, orange</b>`,`pomme, banane, orange`],[`<b lang="en">water, milk, tea, juice</b>`,`eau, lait, thé, jus`]])}
<p>Certains noms sont <b>indénombrables</b> : on ne dit pas « a bread » ni « two breads ». Pour les compter, on utilise un contenant ou une quantité : <b lang="en">a slice of bread</b>, <b lang="en">a glass of milk</b>, <b lang="en">a bottle of water</b>, <b lang="en">a piece of cake</b>.</p>`},
 {t:'Commander poliment et faux amis',h:`<p>Pour commander ou proposer : <b lang="en">Would you like some tea?</b> — <b lang="en">Yes, please.</b> / <b lang="en">No, thank you.</b> Pour demander : <b lang="en">I’d like a sandwich, please.</b> (I’d = I would, plus poli que <b lang="en">I want</b>.)</p>
<p>Faux amis alimentaires : au Royaume-Uni, <b lang="en">chips</b> désigne les frites, alors que les chips s’appellent <b lang="en">crisps</b> ; <b lang="en">biscuit</b> signifie « petit gâteau sec » (aux États-Unis : <b lang="en">cookie</b>).</p>
<p>Prononciation : <b lang="en">vegetable</b> se dit « vèdj-tébeul » (3 syllabes), <b lang="en">sandwich</b> « sannouidj » et <b lang="en">juice</b> « djouss ». Le mot <b lang="en">water</b> se prononce « ouoteu ».</p>
<p>Exemple guidé : « Je voudrais un verre de lait et une part de gâteau, s’il vous plaît. »</p>
${ol([`Politesse : <b lang="en">I’d like</b>.`,`Quantité : <b lang="en">a glass of milk</b>, <b lang="en">a piece of cake</b>.`,`<b lang="en">please</b> à la fin.`])}
<p>Résultat : <b lang="en">I’d like a glass of milk and a piece of cake, please.</b></p>`}],
 try:{q:`Comment demander poliment « un jus d’orange et deux tranches de pain » ?`,a:`I’d like an orange juice and two slices of bread, please. (slice est dénombrable ; bread ne prend pas de s ; an devant orange.)`},
 adult:`Jouez au restaurant avec la vraie nourriture de la maison : l’enfant commande avec I’d like… please, vous répondez Would you like… ? Surveillez l’emploi de I’d like à la place de I want, et l’absence de s sur les noms indénombrables.`,
 culture:{t:`Le sandwich porte un nom de comte`,h:`<p>Le <b lang="en">sandwich</b> doit son nom au comte de Sandwich, un aristocrate britannique du XVIIIe siècle. On raconte qu’il demandait de la viande entre deux tranches de pain pour pouvoir manger sans quitter sa table de jeu. Le nom est ensuite devenu mondial. <b lang="en">Sandwich</b> est aussi une petite ville du comté de Kent, en Angleterre.</p>`}},
'en6y':{
 deep:[{t:'Les parties du corps et leurs pièges',h:`<p>Vocabulaire : <b lang="en">head, hair, face, eyes, ears, nose, mouth, neck, shoulders, arms, hands, fingers, legs, knees, feet, toes</b>. Le pluriel irrégulier à retenir : <b lang="en">foot → feet</b>, <b lang="en">tooth → teeth</b>.</p>
<p>Avec les parties du corps, l’anglais utilise un <b lang="en">possessif</b> là où le français met l’article : <b lang="en">I wash my hands</b> (je me lave les mains), <b lang="en">Raise your arm</b> (lève le bras), <b lang="en">She hurts her knee</b>.</p>
<p>Faux ami : <b lang="en">arm</b> signifie « bras », alors que « arme » se dit <b lang="en">weapon</b>. Autre piège : <b lang="en">hair</b> est indénombrable : <b lang="en">Her hair is long</b> (au singulier).</p>
<p>Prononciation : plusieurs lettres sont muettes : <b lang="en">knee</b> /niː/ (le k ne se prononce pas), <b lang="en">thumb</b> (le b), <b lang="en">head</b> « hèd ».</p>`},
 {t:'Dire où l’on a mal, décrire',h:`<p>Pour dire où on a mal : <b lang="en">My head hurts</b> ou <b lang="en">I’ve got a headache</b>, <b lang="en">I’ve got a stomach ache</b>, <b lang="en">My foot hurts</b>. Pour demander : <b lang="en">What’s the matter?</b> — <b lang="en">I’ve got a sore throat.</b></p>
<p>Pour décrire un personnage ou un monstre : <b lang="en">It’s got three eyes, two big ears and long arms.</b> Le verbe <b lang="en">have got</b> sert à décrire.</p>
<p>Exemple guidé : « Mon frère a mal aux dents. »</p>
${ol([`Possesseur : <b lang="en">my brother</b> = he.`,`« mal aux dents » : <b lang="en">a toothache</b>, nom composé avec <b lang="en">ache</b>.`])}
<p>Résultat : <b lang="en">My brother has got a toothache.</b> ou <b lang="en">His teeth hurt.</b></p>
<p>Prononciation : <b lang="en">stomach</b> se dit « stameuk » (ch = k), <b lang="en">ache</b> se dit « èïk », comme la lettre K.</p>`}],
 try:{q:`Traduis : « Elle se lave les mains et elle a mal à la tête. »`,a:`She washes her hands and she has got a headache. (possessif her devant hands ; washes : -es après sh.)`},
 adult:`Chantez ensemble « Head, Shoulders, Knees and Toes » en touchant chaque partie du corps. Puis inventez un monstre : chacun dessine, l’autre décrit avec « It’s got… ». Corrigez l’article (the hands → my hands) et le pluriel de foot/tooth.`,
 culture:{t:`Break a leg !`,h:`<p>Au théâtre, on dit <b lang="en">Break a leg!</b> à un comédien avant qu’il entre en scène. Cela signifie « bonne chance », mais on ne le souhaite pas vraiment à la lettre. La tradition veut qu’on évite de dire <b lang="en">Good luck</b> aux acteurs. C’est un exemple d’expression idiomatique : le sens ne se déduit pas des mots pris un par un.</p>`}},
'en6z':{
 deep:[{t:'Les animaux et leurs particularités',h:`<p>Animaux familiers et de la ferme : <b lang="en">dog, cat, horse, cow, pig, sheep, chicken, duck, rabbit, mouse</b>. Animaux sauvages : <b lang="en">lion, monkey, elephant, wolf, bear, fox</b>.</p>
<p>Pluriels à retenir : <b lang="en">mouse → mice</b>, <b lang="en">wolf → wolves</b>, <b lang="en">sheep → sheep</b> (ne change pas), <b lang="en">fish → fish</b>. Pour un animal, on utilise <b lang="en">it</b> ; pour un animal de compagnie auquel on s’attache, on utilise souvent <b lang="en">he</b> ou <b lang="en">she</b>.</p>
<p>Faux ami : <b lang="en">pet</b> veut dire « animal de compagnie ». Prononciation : <b lang="en">mouse</b> « maouss », <b lang="en">bird</b> « beurd » (le r est faible), <b lang="en">monkey</b> « monnki », <b lang="en">giraffe</b> « djirâf ».</p>
<p>Verbes utiles : <b lang="en">It can run fast. It lives in water. It eats grass.</b></p>`},
 {t:'Décrire un animal et rédiger un petit portrait',h:`<p>Pour présenter un animal, on peut suivre un modèle de quatre phrases :</p>
${ol([`<b lang="en">It’s a</b> (nom). <b lang="en">It’s</b> (taille, couleur).`,`<b lang="en">It’s got</b> (parties du corps).`,`<b lang="en">It can</b> (capacité).`,`<b lang="en">It lives in</b> (lieu) <b lang="en">and it eats</b> (nourriture).`])}
<p>Exemple guidé : <b lang="en">It’s a rabbit. It’s small and white. It’s got long ears and a short tail. It can jump very fast. It lives in a hutch and it eats carrots.</b> Chaque phrase utilise un outil du programme de 6e : <b lang="en">be</b>, <b lang="en">have got</b>, <b lang="en">can</b> et le présent simple.</p>
<p>Attention à l’accord de <b lang="en">eats</b> et <b lang="en">lives</b>, car le sujet <b lang="en">it</b> demande le s.</p>
<p>Le nom d’un animal peut changer selon qu’on parle de la bête ou de la viande : <b lang="en">cow</b> / <b lang="en">beef</b>, <b lang="en">pig</b> / <b lang="en">pork</b>, <b lang="en">sheep</b> / <b lang="en">mutton</b> (ou <b lang="en">lamb</b>).</p>`}],
 try:{q:`Écris trois phrases sur un chat : sa couleur, ce qu’il a, ce qu’il sait faire.`,a:`Exemple : It’s a black cat. It’s got green eyes and a long tail. It can climb trees. (be, have got, can ; adjectifs avant le nom.)`},
 adult:`Choisissez ensemble un animal et faites écrire à l’enfant un petit portrait en quatre phrases avec le modèle It’s… It’s got… It can… It lives in… Vous pouvez le lire à haute voix : le s de la troisième personne se prononce à l’oral aussi. Montrez-lui les mots cow/beef et pig/pork.`,
 culture:{t:`Pourquoi « pork » et « pig » ?`,h:`<p>Après la conquête de l’Angleterre par les Normands en 1066, les nobles parlaient français et les paysans qui élevaient les bêtes parlaient anglais. C’est pourquoi l’animal vivant a gardé son nom anglais (<b lang="en">cow</b>, <b lang="en">pig</b>, <b lang="en">sheep</b>), alors que la viande servie sur la table a pris un nom d’origine française : <b lang="en">beef</b> (bœuf), <b lang="en">pork</b> (porc), <b lang="en">mutton</b> (mouton).</p>`}},
'en6aa':{
 deep:[{t:'Les objets de la trousse et du cartable',h:`<p>Le matériel de classe : <b lang="en">a pen, a pencil, a rubber</b> (gomme), <b lang="en">a ruler, a pencil case</b> (trousse), <b lang="en">a schoolbag, a notebook, an exercise book, a dictionary, glue, a calculator, scissors</b>.</p>
<p>Attention : <b lang="en">scissors</b> (ciseaux) est toujours pluriel : <b lang="en">a pair of scissors</b>, <b lang="en">my scissors are new</b>. En américain, une gomme se dit <b lang="en">an eraser</b> ; le mot <b lang="en">rubber</b> a un autre sens en américain, donc on préfère <b lang="en">eraser</b> si on parle à un Américain.</p>
<p>Faux amis scolaires importants : <b lang="en">a library</b> est une bibliothèque, pas une librairie (<b lang="en">a bookshop</b>). <b lang="en">A lecture</b> est un cours magistral ou une conférence, pas une lecture (<b lang="en">reading</b>). <b lang="en">A college</b>, au Royaume-Uni, est un établissement d’enseignement après le collège.</p>`},
 {t:'Demander et prêter du matériel',h:`<p>En classe, on utilise souvent ces phrases :</p>
${ul([`<b lang="en">Have you got a rubber, please?</b> (Est-ce que tu as une gomme ?)`,`<b lang="en">Can I borrow your ruler?</b> (Puis-je t’emprunter ta règle ?)`,`<b lang="en">Here you are.</b> (Tiens / Voici.) — <b lang="en">Thank you.</b> — <b lang="en">You’re welcome.</b>`,`<b lang="en">I haven’t got my book.</b> / <b lang="en">I’ve forgotten my pencil case.</b>`])}
<p>Le verbe <b lang="en">borrow</b> signifie « emprunter » (prendre) et <b lang="en">lend</b> signifie « prêter » (donner pour un temps). Piège : <b lang="en">Can you borrow me your pen?</b> est faux. On dit <b lang="en">Can I borrow your pen?</b> ou <b lang="en">Can you lend me your pen?</b></p>
<p>Prononciation : <b lang="en">pencil</b> « pènsil », <b lang="en">scissors</b> « sizeurz » (le c est muet), <b lang="en">calculator</b> « calkiouleïteur ».</p>
<p>Exemple guidé : « Peux-tu me prêter ta règle ? Je n’ai pas ma trousse. » → <b lang="en">Can you lend me your ruler? I haven’t got my pencil case.</b></p>`}],
 try:{q:`Traduis : « Puis-je emprunter ton dictionnaire, s’il te plaît ? Il est sur ta table. »`,a:`Can I borrow your dictionary, please? It’s on your table. (borrow : c’est moi qui emprunte.)`},
 adult:`Mettez cinq objets de la trousse sur la table et faites poser des demandes polies : « Can I borrow… ? Have you got… ? Here you are. » Repérez les confusions borrow/lend et library/bookshop. Faites épeler le mot scissors, dont le premier c est muet.`,
 culture:{t:`Le « plomb » du crayon n’en contient pas`,h:`<p>La mine d’un crayon à papier s’appelle <b lang="en">lead</b> (plomb) en anglais, mais elle ne contient pas de plomb : c’est du graphite, mélangé à de l’argile. Ce minéral a été découvert au XVIe siècle près de Borrowdale, en Angleterre. On l’a d’abord pris pour une sorte de plomb, d’où le nom qui est resté.</p>`}},
'en6ab':{
 deep:[{t:'Pays, nationalités et langues',h:`<p>Le nom du pays et la nationalité sont deux mots différents :</p>
${tb([[`<b lang="en">France</b>`,`<b lang="en">French</b>`],[`<b lang="en">England</b>`,`<b lang="en">English</b>`],[`<b lang="en">Spain</b>`,`<b lang="en">Spanish</b>`],[`<b lang="en">Italy</b>`,`<b lang="en">Italian</b>`],[`<b lang="en">Germany</b>`,`<b lang="en">German</b>`],[`<b lang="en">Scotland</b>`,`<b lang="en">Scottish</b>`],[`<b lang="en">Ireland</b>`,`<b lang="en">Irish</b>`],[`<b lang="en">the USA</b>`,`<b lang="en">American</b>`]])}
<p>Les pays, les nationalités et les langues prennent <b>toujours une majuscule</b> en anglais. La nationalité sert aussi de nom de langue : <b lang="en">I speak French and English</b>.</p>
<p>Pour dire d’où l’on vient : <b lang="en">Where are you from?</b> — <b lang="en">I’m from France.</b> ou <b lang="en">I’m French.</b> Les deux sont corrects, mais on ne dit pas « I’m from French ».</p>`},
 {t:'Royaume-Uni, Grande-Bretagne, Angleterre',h:`<p>Ces trois mots ne sont pas synonymes :</p>
${ul([`<b lang="en">England</b>, <b lang="en">Scotland</b> et <b lang="en">Wales</b> (pays de Galles) sont trois pays.`,`<b lang="en">Great Britain</b> est l’île qui regroupe ces trois pays.`,`<b lang="en">The United Kingdom</b> (<b lang="en">UK</b>) comprend les trois pays de la Grande-Bretagne et l’Irlande du Nord.`])}
<p>Prononciation : l’accent tonique change avec le mot : <b lang="en">ENgland</b> mais <b lang="en">EngLISH</b>, <b lang="en">ITaly</b> mais <b lang="en">iTALian</b>, <b lang="en">GERmany</b> mais <b lang="en">GERman</b>. Le <b lang="en">g</b> de <b lang="en">German</b> se prononce « dj » : « djeurmeun ».</p>
<p>Exemple guidé : « Mon amie Sofia est italienne ; ses parents viennent de Rome mais ils habitent en Espagne. »</p>
${ol([`Nationalité (adjectif) : <b lang="en">Italian</b>, avec une majuscule.`,`Origine : <b lang="en">come from Rome</b> (venir de).`,`Habiter : <b lang="en">live in Spain</b>.`])}
<p>Résultat : <b lang="en">My friend Sofia is Italian. Her parents come from Rome, but they live in Spain.</b></p>`}],
 try:{q:`Traduis : « Il est écossais et elle est galloise. »`,a:`He’s Scottish and she’s Welsh. (nationalités avec une majuscule ; he’s, she’s = he is, she is.)`},
 adult:`Montrez une carte du monde et demandez Where is it? / What nationality are they? Faites trier les mots England, Great Britain et UK. Pour la prononciation, concentrez-vous sur la place de l’accent : l’enfant doit sentir que EngLISH n’a pas le même rythme que ENgland.`,
 culture:{t:`Qui est dans le Royaume-Uni ?`,h:`<p>Le <b lang="en">Royaume-Uni</b> est formé de quatre nations : l’Angleterre, l’Écosse, le pays de Galles et l’Irlande du Nord. Chacune a son drapeau. Le <b lang="en">Union Jack</b>, le drapeau du Royaume-Uni, combine les croix de Saint-Georges (Angleterre), de Saint-André (Écosse) et de Saint-Patrick (Irlande). Le pays de Galles a son propre drapeau, avec un dragon rouge.</p>`}},
'en6ac':{
 deep:[{t:'Comprendre et donner des consignes',h:`<p>En classe d’anglais, la plupart des consignes sont à l’<b>impératif</b> : le verbe est à la forme de base, sans sujet. La négation s’obtient avec <b lang="en">don’t</b>.</p>
${tb([[`<b lang="en">Open your books.</b>`,`Ouvrez vos livres.`],[`<b lang="en">Listen to the CD.</b>`,`Écoutez l’enregistrement.`],[`<b lang="en">Look at the board.</b>`,`Regardez le tableau.`],[`<b lang="en">Work in pairs.</b>`,`Travaillez à deux.`],[`<b lang="en">Don’t talk, please.</b>`,`Ne parlez pas, s’il vous plaît.`],[`<b lang="en">Sit down. / Stand up.</b>`,`Asseyez-vous. / Levez-vous.`]])}
<p>On ajoute <b lang="en">please</b> pour être poli. Pour s’adresser à une seule personne ou à tout le groupe, la forme est la même (<b lang="en">you</b> sert pour « tu » et « vous »).</p>`},
 {t:'Demander de l’aide en anglais',h:`<p>Voici les phrases à connaître pour ne jamais rester bloqué :</p>
${ul([`<b lang="en">I don’t understand.</b> — Je ne comprends pas.`,`<b lang="en">Can you repeat, please?</b> — Pouvez-vous répéter ?`,`<b>How do you say « livre » in English?</b>`,`<b lang="en">What does « borrow » mean?</b> — Que signifie borrow ?`,`<b lang="en">How do you spell it?</b>`,`<b lang="en">Can I go to the toilet, please?</b>`])}
<p>Prononciation : plusieurs lettres sont muettes. <b lang="en">Listen</b> se dit « lissène » (le t est muet), <b lang="en">write</b> « raït » (le w est muet), <b lang="en">answer</b> « ânseu » (le w est muet), <b lang="en">board</b> « bôrd ».</p>
<p>Faux ami : <b lang="en">to attend</b> signifie « assister à » (un cours), alors que <b lang="en">to assist</b> veut dire « aider ». Au Royaume-Uni, les élèves appellent souvent leur enseignant <b lang="en">Sir</b> (homme) ou <b lang="en">Miss</b> (femme).</p>
<p>Exemple guidé : l’enseignant dit <b lang="en">Work in pairs and don’t use your books.</b> → je comprends deux ordres reliés par <b lang="en">and</b>. Le premier est affirmatif : je dois travailler à deux. Le second est négatif (<b lang="en">don’t</b>) : je ne dois pas utiliser mes livres.</p>`}],
 try:{q:`Que signifie « Don’t open your books. Listen and repeat. » ?`,a:`N’ouvrez pas vos livres. Écoutez et répétez. (don’t = interdiction ; listen and repeat : deux impératifs.)`},
 adult:`Jouez à « Simon says » : donnez des consignes en anglais (Stand up, Touch your nose, Don’t move) et l’enfant les exécute, puis il vous en donne à son tour. C’est une excellente façon de s’entraîner à l’impératif et à la négation.`,
 culture:{t:`« Miss » et « Sir » dans les écoles britanniques`,h:`<p>Dans les écoles britanniques, les élèves appellent souvent leur enseignante <b lang="en">Miss</b>, quel que soit son statut, et leur enseignant <b lang="en">Sir</b>. Les élèves portent généralement un uniforme. Au moment de l’appel, ils répondent <b lang="en">Here</b> ou <b lang="en">Present</b> quand on prononce leur nom.</p>`}},
'en6ad':{
 deep:[{t:'Les mots interrogatifs',h:`<p>Pour poser une question d’information, on commence par un mot interrogatif :</p>
${tb([[`<b lang="en">What</b>`,`quoi / que`],[`<b lang="en">Where</b>`,`où`],[`<b lang="en">Who</b>`,`qui`],[`<b lang="en">When</b>`,`quand`],[`<b lang="en">Why</b>`,`pourquoi (réponse : <b lang="en">because</b>)`],[`<b lang="en">How</b>`,`comment`],[`<b lang="en">How many</b> + pluriel`,`combien de (dénombrable)`],[`<b lang="en">How much</b> + indénombrable`,`combien (de)`],[`<b lang="en">How old</b>`,`quel âge`]])}
<p>Piège : <b lang="en">How many books?</b> mais <b lang="en">How much water?</b> Si le nom a un pluriel, c’est <b lang="en">many</b> ; sinon <b lang="en">much</b>.</p>
<p>Les journalistes retiennent les « 5 W » : <b lang="en">Who, What, When, Where, Why</b> (et <b lang="en">How</b>) pour ne rien oublier d’une information.</p>`},
 {t:'La construction de la question',h:`<p>Avec le verbe <b lang="en">be</b>, on inverse simplement : <b lang="en">Where is the school?</b>, <b lang="en">Who are they?</b>, <b lang="en">How old is she?</b></p>
<p>Avec un autre verbe, on utilise <b lang="en">do/does</b> : <b lang="en">Where do you live?</b>, <b lang="en">What does she like?</b> Le verbe reprend sa forme de base après <b lang="en">does</b>.</p>
<p>Exemple guidé : « Où habite ton cousin ? » → mot interrogatif <b lang="en">where</b> ; verbe <b lang="en">live</b> ; sujet à la troisième personne → <b lang="en">does</b>. Résultat : <b lang="en">Where does your cousin live?</b> (et non « Where lives your cousin ? »).</p>
<p>L’intonation aide aussi à comprendre : elle <b lang="en">descend</b> à la fin d’une question avec un mot interrogatif (<b lang="en">Where do you live?</b> ↘) et <b lang="en">monte</b> à la fin d’une question appelant oui ou non (<b lang="en">Do you live in Paris?</b> ↗).</p>
<p>Prononciation : <b lang="en">where</b> « ouère » avec w comme dans « oui », <b lang="en">who</b> « hou », <b lang="en">why</b> « ouaï ». Ne confonds pas <b lang="en">where</b> (où) avec <b lang="en">wear</b> (porter) : ils se prononcent de la même façon.</p>`}],
 try:{q:`Pose la question qui correspond à la réponse : « She is twelve. »`,a:`How old is she? (on demande l’âge avec how old + be.)`},
 adult:`Faites un jeu d’interview : l’enfant vous pose cinq questions sur votre vie avec who, where, when, why, how. Vous répondez en anglais, lentement. Corrigez l’inversion (Where is…) et l’emploi de do/does. Demandez-lui de faire monter ou descendre la voix selon le type de question.`,
 culture:{t:`Les cinq W du journalisme`,h:`<p>Dans les écoles de journalisme anglo-saxonnes, on apprend les « cinq W » : <b lang="en">Who</b>? <b lang="en">What</b>? <b lang="en">When</b>? <b lang="en">Where</b>? <b lang="en">Why</b>? Un bon article répond à ces cinq questions dès les premières lignes. Cette méthode simple t’aide aussi à résumer un texte ou à préparer un exposé.</p>`}},
'en6ae':{
 deep:[{t:'Décrire le physique avec BE et HAVE GOT',h:`<p>Pour décrire une personne ou un personnage, on utilise deux structures que tu connais déjà.</p>
${tb([[`<b lang="en">be</b> + adjectif`,`<b lang="en">She is tall and thin.</b> <b lang="en">He is young.</b>`],[`<b lang="en">have got</b> + nom`,`<b lang="en">She has got long brown hair.</b> <b lang="en">He has got blue eyes.</b>`]])}
<p>Dans un portrait, on suit souvent cet ordre : <b lang="en">taille</b> (tall, short), <b>âge</b> (young, old), <b lang="en">cheveux</b> (short, long, curly, straight, blond, dark), <b lang="en">yeux</b> (blue, green, brown), puis <b>vêtements</b>. L’adjectif se place avant le nom et ne prend jamais de s : <b lang="en">two blue eyes</b>.</p>
<p>Piège : en français, on dit « elle a les cheveux longs » ; en anglais, <b lang="en">She has got long hair</b>, avec l’adjectif avant <b lang="en">hair</b>, et sans article. Autre piège : <b lang="en">He looks</b> + adjectif signifie « Il a l’air… » : <b lang="en">He looks friendly</b>. Ne dis pas « He looks like friendly ».</p>
<p>Pour poser la question : <b lang="en">What does she look like?</b> (À quoi ressemble-t-elle ?) — ne la confonds pas avec <b lang="en">What is she like?</b> (Comment est-elle de caractère ?).</p>`},
 {t:'Décrire le caractère et relier les idées',h:`<p>Adjectifs de caractère à connaître : <b lang="en">kind</b> (gentil), <b lang="en">brave</b> (courageux), <b lang="en">funny</b> (drôle), <b lang="en">shy</b> (timide), <b lang="en">clever</b> (intelligent), <b lang="en">lazy</b> (paresseux), <b lang="en">friendly</b> (sympathique), <b lang="en">generous</b>. Faux ami : <b lang="en">sensible</b> signifie « raisonnable, de bon sens », et non « sensible » (qui se dit <b lang="en">sensitive</b>).</p>
<p>Pour relier tes phrases, utilise <b lang="en">and</b>, <b lang="en">but</b>, <b lang="en">because</b> : <b lang="en">He is shy but he is very kind.</b> <b lang="en">I like her because she is funny.</b> Pour nuancer : <b lang="en">very</b> (très), <b lang="en">quite</b> (assez), <b lang="en">a bit</b> (un peu) se placent devant l’adjectif.</p>
<p>Exemple guidé : « Mon héros est grand, il a les cheveux courts et noirs. Il est courageux mais un peu timide. »</p>
${ol([`Physique avec be et have got : <b lang="en">He is tall. He has got short black hair.</b>`,`Caractère avec but et a bit : <b lang="en">He is brave but a bit shy.</b>`])}
<p>Résultat : <b lang="en">My hero is tall. He has got short black hair. He is brave but a bit shy.</b></p>
<p>Prononciation : <b lang="en">friendly</b> se dit « frèndli », <b lang="en">generous</b> « djénérès », <b lang="en">curly</b> « keurli ».</p>`}],
 try:{q:`Décris un personnage en trois phrases : « Elle est petite, elle a de longs cheveux roux, elle est drôle mais timide. »`,a:`She is short. She has got long red hair. She is funny but shy. (be pour la taille et le caractère, have got pour les cheveux.)`},
 adult:`Choisissez un personnage connu de l’enfant (un héros de film ou de livre) et demandez-lui de le décrire en anglais sans le nommer ; vous devinez. Exigez les deux structures be et have got, et corrigez le s après un adjectif ainsi que « He is got ». Terminez par What is he like? pour le caractère.`,
 culture:{t:`Des personnages qui voyagent`,h:`<p>Beaucoup de personnages célèbres de la littérature anglophone sont connus dans le monde entier : <b lang="en">Sherlock Holmes</b>, le détective créé par Arthur Conan Doyle, <b lang="en">Alice</b> d’<b lang="en">Alice’s Adventures in Wonderland</b> (Lewis Carroll, 1865) ou <b lang="en">Harry Potter</b> de J. K. Rowling. Pour les décrire, on commence presque toujours par leur apparence, puis leur caractère : les mêmes structures que tu viens d’étudier.</p>`}},
'en6af':{
 deep:[{t:'L’emploi du temps et les matières',h:`<p>Les matières en anglais : <b lang="en">maths</b>, <b lang="en">English</b>, <b lang="en">French</b>, <b lang="en">history</b>, <b lang="en">geography</b>, <b lang="en">science</b>, <b lang="en">art</b>, <b lang="en">music</b>, <b lang="en">PE</b> (physical education, l’EPS), <b lang="en">IT</b>. Les noms de langues prennent une majuscule. Le mot <b lang="en">lesson</b> désigne un cours ; <b lang="en">subject</b> une matière.</p>
<p>Pour parler de ta journée au présent simple : <b lang="en">School starts at eight thirty.</b> <b lang="en">We have maths on Monday.</b> <b lang="en">Lessons finish at four.</b> Pour les repas : <b lang="en">have lunch at the canteen</b>. Pour la récréation : <b lang="en">break time</b>.</p>
<p>Prépositions : <b lang="en">at</b> + heure, <b lang="en">on</b> + jour, <b lang="en">in</b> + moment de la journée : <b lang="en">at nine o’clock</b>, <b lang="en">on Tuesdays</b>, <b lang="en">in the afternoon</b>. Attention à <b lang="en">on Tuesdays</b> (tous les mardis) avec un s.</p>`},
 {t:'Raconter sa journée et donner son avis',h:`<p>Pour raconter sa journée, enchaîne les verbes avec <b lang="en">first</b>, <b lang="en">then</b>, <b lang="en">after that</b>, <b lang="en">finally</b>. Pour donner un avis : <b lang="en">My favourite subject is history because it is interesting.</b> <b lang="en">I don’t like maths because it is difficult.</b></p>
<p>Verbes utiles : <b lang="en">get up</b>, <b lang="en">have breakfast</b>, <b lang="en">go to school</b> (sans article), <b lang="en">do homework</b>, <b lang="en">play</b> + sport, <b lang="en">go home</b> (sans to). Avec <b lang="en">home</b>, pas de préposition : <b lang="en">I go home</b>, <b lang="en">I am at home</b>.</p>
<p>Exemple guidé : « Le lundi, j’ai maths à neuf heures, puis anglais. Après l’école, je joue au basket. »</p>
${ol([`Jour répété : <b lang="en">On Mondays</b>.`,`Heure : <b lang="en">at nine</b>.`,`Loisir : <b lang="en">play basketball</b> (sans the).`])}
<p>Résultat : <b lang="en">On Mondays, I have maths at nine, then English. After school, I play basketball.</b></p>
<p>Prononciation : <b lang="en">Wednesday</b> « ouènzdé », <b lang="en">science</b> « saïens », <b lang="en">geography</b> « djiogrefi », <b lang="en">favourite</b> « féïvrit » (trois syllabes réduites à deux).</p>`}],
 try:{q:`Traduis : « Le mardi, les cours commencent à huit heures et finissent à quatre heures. »`,a:`On Tuesdays, lessons start at eight and finish at four. (on + jour avec s pour l’habitude ; at + heure.)`},
 adult:`Faites décrire en anglais l’emploi du temps d’une journée type en six phrases avec first, then, after that. Contrôlez on / at / in, l’absence d’article dans go to school et play football, et la prononciation de Wednesday et favourite.`,
 culture:{t:`Year 7 au Royaume-Uni`,h:`<p>En Angleterre, les élèves entrent au collège en <b lang="en">Year 7</b>, vers 11 ans, ce qui correspond à peu près à la 6e française. Beaucoup portent un uniforme et appellent leurs professeurs <b lang="en">Sir</b> ou <b lang="en">Miss</b>. Les repas se prennent souvent à la cantine, ou avec un <b lang="en">packed lunch</b> (un repas préparé à la maison et emporté dans une boîte).</p>`}},
'en6ag':{
 deep:[{t:'Les paysages et la géographie de base',h:`<p>Vocabulaire à connaître : <b lang="en">mountain</b>, <b lang="en">hill</b>, <b lang="en">river</b>, <b lang="en">lake</b>, <b lang="en">sea</b>, <b lang="en">beach</b>, <b lang="en">coast</b>, <b lang="en">island</b>, <b lang="en">forest</b>, <b lang="en">field</b>, <b lang="en">city</b>, <b lang="en">village</b>, <b lang="en">countryside</b> (la campagne).</p>
<p>Pour décrire, on utilise <b lang="en">there is / there are</b> : <b lang="en">There are high mountains in Scotland.</b> <b lang="en">There is a long river in London.</b> Pour situer : <b lang="en">in the north / south / east / west of</b> : <b lang="en">Edinburgh is in the east of Scotland.</b></p>
<p>Prononciation : <b lang="en">mountain</b> se dit « maountine », <b lang="en">island</b> « aïlend » (le <b lang="en">s</b> est muet), <b lang="en">countryside</b> « kantrisaïd », <b lang="en">river</b> « rive-eur ».</p>
<p>Piège : <b lang="en">the north</b> prend un article, mais <b lang="en">north of France</b> sans article (<b lang="en">north of</b>). On écrit aussi les points cardinaux avec une minuscule sauf pour un nom propre (<b lang="en">the North Sea</b>).</p>`},
 {t:'Décrire un paysage et comparer',h:`<p>Pour décrire un paysage avec des adjectifs : <b lang="en">high</b> (haut), <b lang="en">long</b>, <b lang="en">wide</b> (large), <b lang="en">beautiful</b>, <b lang="en">quiet</b>, <b lang="en">busy</b> (animé), <b lang="en">green</b>. Le verbe <b lang="en">can</b> permet d’ajouter une action : <b lang="en">You can see the sea from the hill.</b></p>
<p>Pour comparer en 6e, on peut rester simple : <b lang="en">London is bigger than Edinburgh.</b> <b lang="en">The mountains are higher than the hills.</b> (comparatif en <b lang="en">-er</b> pour les mots courts, sujet étudié en 4e).</p>
<p>Exemple guidé : « Au nord de l’Angleterre, il y a des collines vertes, un lac très grand et un petit village. »</p>
${ol([`Lieu : <b lang="en">In the north of England</b>.`,`Présentation : <b lang="en">there are</b> pour le pluriel, <b lang="en">there is</b> pour le singulier.`,`Adjectif avant le nom : <b lang="en">green hills</b>, <b lang="en">a very big lake</b>.`])}
<p>Résultat : <b lang="en">In the north of England, there are green hills, a very big lake and a small village.</b></p>`}],
 try:{q:`Traduis : « Il y a une grande île au sud et des montagnes à l’ouest. »`,a:`There is a big island in the south and there are mountains in the west. (there is / there are selon le nom ; in the south / in the west.)`},
 adult:`Montrez une carte (ou une photo de paysage) et demandez à l’enfant de la décrire en trois phrases avec there is / there are et un point cardinal. Faites répéter island (le s est muet) et mountain. Un bon défi : décrire le paysage près de chez vous, puis celui d’un pays anglophone.`,
 culture:{t:`Des paysages très variés`,h:`<p>Le Royaume-Uni compte des paysages très différents : les montagnes des <b lang="en">Highlands</b> en Écosse, les collines vertes du <b lang="en">Lake District</b> en Angleterre ou les falaises blanches de <b lang="en">Dover</b> dans le sud-est de l’Angleterre. Le point culminant du pays, <b lang="en">Ben Nevis</b>, se trouve en Écosse et mesure environ 1 345 mètres.</p>`}},
'en6ah':{
 deep:[{t:'Les éléments d’une légende',h:`<p>Une légende ou un conte met en scène des personnages, un lieu, un problème et une fin. Vocabulaire : <b lang="en">a king</b>, <b lang="en">a queen</b>, <b lang="en">a knight</b> (chevalier, le <b lang="en">k</b> est muet), <b lang="en">a castle</b> (le <b lang="en">t</b> est muet), <b lang="en">a dragon</b>, <b lang="en">a wizard</b>, <b lang="en">a forest</b>, <b lang="en">a treasure</b>, <b lang="en">a sword</b> (le <b lang="en">w</b> est muet).</p>
<p>Un conte commence souvent par <b lang="en">Once upon a time, there was…</b> (« Il était une fois… »). Pour présenter les personnages : <b lang="en">The knight lives in an old castle. He is brave.</b> On utilise le présent simple pour résumer l’histoire.</p>
<p>Pour décrire un lieu : <b lang="en">There is a dark forest near the castle.</b> Pour décrire un personnage : <b lang="en">The dragon is big and dangerous.</b></p>
<p>Prononciation : <b lang="en">knight</b> « naït », <b lang="en">castle</b> « kâsl », <b lang="en">sword</b> « sôd », <b lang="en">dangerous</b> « dèïndjerès ».</p>`},
 {t:'Raconter avec first, then, finally',h:`<p>Pour raconter simplement une histoire, enchaîne des phrases courtes avec des mots de liaison : <b lang="en">First</b>, <b lang="en">then</b>, <b lang="en">next</b>, <b lang="en">after that</b>, <b lang="en">finally</b>, et <b lang="en">but</b> pour le problème.</p>
<p>Exemple guidé. Résumer en quatre phrases : « Un chevalier part dans la forêt. Il trouve un dragon, mais le dragon est gentil. Ils deviennent amis. »</p>
${ol([`<b lang="en">First, the knight goes into the forest.</b>`,`<b lang="en">Then he finds a dragon.</b>`,`<b lang="en">But the dragon is friendly.</b>`,`<b lang="en">Finally, they become friends.</b>`])}
<p>Verbes à connaître : <b lang="en">find</b> (trouver), <b lang="en">help</b>, <b lang="en">save</b> (sauver), <b lang="en">live</b>, <b lang="en">fight</b> (se battre), <b lang="en">become</b> (devenir). Au présent simple, n’oublie pas le <b lang="en">s</b> à he/she/it : <b lang="en">he finds</b>, <b lang="en">she saves</b>.</p>
<p>Pour donner son avis sur l’histoire : <b lang="en">I like this story because it is exciting.</b> <b lang="en">The end is sad.</b></p>`}],
 try:{q:`Traduis : « Il était une fois une reine qui vivait dans un grand château. »`,a:`Once upon a time, there was a queen. She lived in a big castle. (Once upon a time, there was… pour ouvrir le conte, puis deux phrases courtes.)`},
 adult:`Racontez ensemble une légende ou un conte connu en anglais, phrase par phrase, en utilisant first, then, but, finally. L’enfant ajoute une phrase à chaque tour. Faites prononcer knight, castle, sword (lettres muettes) et surveillez le s de la 3e personne.`,
 culture:{t:`Arthur, Robin Hood, Nessie`,h:`<p>Les légendes britanniques les plus connues sont celles du roi <b lang="en">Arthur</b> et des chevaliers de la Table ronde, de <b lang="en">Robin Hood</b>, le hors-la-loi de la forêt de Sherwood, et du monstre du <b lang="en">Loch Ness</b> en Écosse, surnommé <b lang="en">Nessie</b>. Ces histoires mélangent des éléments historiques et imaginaires, et elles inspirent encore de nombreux films et livres.</p>`}},
'en6ai':{
 deep:[{t:'Dire ce qu’on ressent',h:`<p>Adjectifs de sentiments : <b lang="en">happy</b>, <b lang="en">sad</b>, <b lang="en">angry</b>, <b lang="en">excited</b>, <b lang="en">scared</b>, <b lang="en">surprised</b>, <b lang="en">tired</b>, <b lang="en">nervous</b>, <b lang="en">proud</b>. On les emploie avec <b lang="en">be</b> : <b lang="en">I am happy.</b> <b lang="en">She is scared.</b></p>
<p>Pour dire qu’une œuvre provoque une émotion : <b lang="en">This song makes me feel happy.</b> <b lang="en">This picture makes me sad.</b> Après <b lang="en">make me feel</b>, on met un adjectif, jamais un nom.</p>
<p>Piège important : les adjectifs en <b lang="en">-ed</b> et en <b lang="en">-ing</b> ne veulent pas dire la même chose. <b lang="en">I am bored</b> (je m’ennuie) mais <b lang="en">The film is boring</b> (le film est ennuyeux). <b lang="en">-ed</b> décrit la personne qui ressent, <b lang="en">-ing</b> décrit ce qui provoque l’émotion. Même chose : <b lang="en">excited / exciting</b>, <b lang="en">interested / interesting</b>.</p>`},
 {t:'Donner son avis sur une œuvre',h:`<p>Pour parler d’un tableau, d’une chanson ou d’une scène de théâtre, tu peux utiliser : <b lang="en">I like / love / don’t like</b>, <b lang="en">I think it is beautiful / strange / funny</b>, <b lang="en">It is about…</b> (Ça parle de…), <b lang="en">I can see…</b> (Je vois…), <b lang="en">The colours are bright</b> (vives) <b lang="en">/ dark</b> (sombres).</p>
<p>Vocabulaire des arts : <b lang="en">a painting</b>, <b lang="en">a picture</b>, <b lang="en">a song</b>, <b lang="en">a singer</b>, <b lang="en">a play</b> (une pièce de théâtre), <b lang="en">an actor</b>, <b lang="en">a drawing</b>. Faux ami : <b lang="en">a play</b> est une pièce de théâtre, pas une « plaie ». Le mot <b lang="en">museum</b> se prononce « miouziem ».</p>
<p>Exemple guidé : « Ce tableau me rend triste parce que les couleurs sont sombres, mais j’aime le paysage. »</p>
${ol([`Émotion : <b lang="en">This painting makes me feel sad</b>.`,`Cause : <b lang="en">because the colours are dark</b>.`,`Avis positif : <b lang="en">but I like the landscape</b>.`])}
<p>Résultat : <b lang="en">This painting makes me feel sad because the colours are dark, but I like the landscape.</b></p>`}],
 try:{q:`Choisis -ed ou -ing : « The film is (bore). I am (bore). »`,a:`The film is boring. I am bored. (-ing pour ce qui cause l’émotion, -ed pour la personne qui la ressent.)`},
 adult:`Montrez une reproduction de tableau ou écoutez un morceau de musique avec l’enfant, puis demandez-lui : What can you see? How does it make you feel? Do you like it? Surveillez bored/boring, excited/exciting et l’adjectif (et non un nom) après make me feel.`,
 culture:{t:`Les couleurs et les émotions`,h:`<p>En anglais, de nombreuses expressions associent une couleur à une émotion : <b lang="en">to feel blue</b> signifie « avoir le cafard », <b lang="en">to be green with envy</b> « être vert de jalousie », <b lang="en">to see red</b> « voir rouge, être furieux ». Comme en français, ces expressions ne se traduisent pas toujours mot à mot : on ne dit pas « je me sens bleu » en français.</p>`}}
});
})(typeof window!=='undefined'?window:globalThis);
